window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"gamma-definition":{"id":"gamma-definition","prerequisites":["integration-by-parts","u-sub-basic","u-sub-definite","improper-infinite","improper-singular","improper-p-test"],"next":["gamma-recurrence-apps","gamma-half"],"related":[],"objectives":["寫得出 $\\Gamma(s)$ 的積分定義，說得出這個積分什麼時候收斂。","用分部積分推出 $\\Gamma(s+1)=s\\Gamma(s)$，以及 $\\Gamma(n+1)=n!$。","把 $\\int_0^{\\infty}x^ke^{-x}\\,dx$ 這類積分直接讀成 Gamma 函數的值。"],"concept":[{"heading":"① 為什麼要學它：一整族積分其實是同一個函數","body":["前面分部積分時會反覆遇到 $\\int_0^{\\infty}xe^{-x}\\,dx$、$\\int_0^{\\infty}x^2e^{-x}\\,dx$、$\\int_0^{\\infty}x^3e^{-x}\\,dx$……每一個都要分部積分好幾次。","Gamma 函數把這一整族積分統一成一個函數。之後看到這種形狀，就不用再算，直接讀值。而它在整數點剛好是階乘，等於把 $n!$ 延伸成一條平滑曲線。"],"tex":["\\Gamma(s)=\\int_0^{\\infty}x^{s-1}e^{-x}\\,dx"]},{"heading":"② 這個積分什麼時候收斂","body":["這是兩端都要檢查的瑕積分：","$x\\to\\infty$：$e^{-x}$ 衰減得比任何 $x$ 的次方增長都快，尾巴收斂。","$x\\to 0^+$：$e^{-x}\\to 1$，被積函數像 $x^{s-1}$。由 $p$ 判別，$\\int_0^1x^{s-1}\\,dx$ 收斂若且唯若 $s-1>-1$，也就是 $s>0$。","所以：此積分表示式在 $s>0$ 時收斂。"]},{"heading":"預告：$s\\le 0$ 呢？","body":["積分在 $s\\le 0$ 發散，但 Gamma 函數可以用別的方法延伸到負的非整數（例如用遞迴 $\\Gamma(s)=\\frac{\\Gamma(s+1)}{s}$ 往左推）。這叫解析延拓。在 $0$、$-1$、$-2$、……仍然沒有定義。"],"collapsible":true},{"heading":"③ 第一個值：$\\Gamma(1)=1$","body":["$s=1$ 時 $x^0=1$，$\\Gamma(1)=\\int_0^{\\infty}e^{-x}\\,dx=1$。"]},{"heading":"④ 遞迴：$\\Gamma(s+1)=s\\Gamma(s)$","body":["對 $\\Gamma(s+1)=\\int_0^{\\infty}x^se^{-x}\\,dx$ 做分部積分，令 $u=x^s$、$dv=e^{-x}\\,dx$。","邊界項：$x\\to\\infty$ 時 $e^{-x}$ 贏過 $x^s$，趨近 $0$；$x=0$ 時 $x^s=0$（$s>0$）。所以邊界項是 $0$，剩下 $\\Gamma(s+1)=s\\Gamma(s)$。"],"tex":["\\Gamma(s+1)=\\Bigl[-x^{s}e^{-x}\\Bigr]_0^{\\infty}+s\\int_0^{\\infty}x^{s-1}e^{-x}\\,dx=s\\,\\Gamma(s)"]},{"heading":"⑤ 在整數點就是階乘","body":["從 $\\Gamma(1)=1$ 開始：$\\Gamma(2)=1$，$\\Gamma(3)=2$，$\\Gamma(4)=6$，……一般地 $\\Gamma(n+1)=n!$。","注意差一：$\\Gamma(n)=(n-1)!$，不是 $n!$。"]},{"heading":"⑥ 讀積分：看到 $x^ke^{-x}$ 就是 Gamma","body":["$\\int_0^{\\infty}x^ke^{-x}\\,dx=\\Gamma(k+1)$。指數裡有常數 $a>0$ 時，換元 $u=ax$，得到下面的公式。"],"tex":["\\int_0^{\\infty}x^{k}e^{-ax}\\,dx=\\frac{\\Gamma(k+1)}{a^{k+1}}"]}],"workedExamples":[{"title":"直接讀成 Gamma","prompt":"$\\int_0^{\\infty}x^2e^{-x}\\,dx$","problemId":"mob-gamma-006","steps":["形狀是 $x^ke^{-x}$，$k=2$，所以是 $\\Gamma(3)$。","$\\Gamma(3)=2!=2$。"],"answer":"$2$","note":"分部積分兩次也會得到 $2$，但要寫半頁。"},{"title":"整數點的值","prompt":"$\\Gamma(6)$ 與 $\\Gamma(4)$","steps":["$\\Gamma(n+1)=n!$，所以 $\\Gamma(6)=5!=120$。","$\\Gamma(4)=3!=6$。"],"answer":"$\\Gamma(6)=120$，$\\Gamma(4)=6$","note":"不要寫成 $\\Gamma(6)=6!=720$，那是差一的錯。"},{"title":"指數裡有常數","prompt":"$\\int_0^{\\infty}x^4e^{-3x}\\,dx$","problemId":"burst-int-001","steps":["令 $u=3x$，$x=\\frac{u}{3}$，$dx=\\frac{du}{3}$。$x^4=\\frac{u^4}{3^4}$。","積分變成 $\\frac{1}{3^5}\\int_0^{\\infty}u^4e^{-u}\\,du=\\frac{\\Gamma(5)}{3^5}$。","$\\Gamma(5)=4!=24$，$3^5=243$，答案是 $\\frac{24}{243}=\\frac{8}{81}$。"],"answer":"$\\frac{8}{81}$"},{"title":"先換元才看得出來","prompt":"$\\int_0^{\\infty}x^3e^{-x^2}\\,dx$","problemId":"depth-int-026","steps":["指數是 $-x^2$，不是標準形狀。令 $u=x^2$，$du=2x\\,dx$。","把 $x^3\\,dx$ 拆成 $x^2\\cdot x\\,dx=u\\cdot\\frac{du}{2}$。","積分變成 $\\frac{1}{2}\\int_0^{\\infty}ue^{-u}\\,du=\\frac{1}{2}\\Gamma(2)=\\frac{1}{2}$。"],"answer":"$\\frac{1}{2}$"}],"pitfalls":["差一：$\\Gamma(n)$ 寫成 $n!$。","換元時漏了 $du$ 的係數，或 $a^{k+1}$ 寫成 $a^k$。","以為 $\\Gamma(0)=0!=1$。$\\Gamma(0)$ 的積分在 $x\\to 0$ 發散，$\\Gamma$ 在 $0$ 沒有定義。"],"figures":[{"caption":"s 是整數時，面積是 (s − 1)!","after":0,"widget":{"type":"family","f":"x^(s-1)*exp(-x)","param":"s","range":[1,4],"step":0.05,"value":3,"area":[0,60],"window":[0,12,0,1.5]}}],"voice":"92485b69","sections":[{"title":"一整族積分","beats":[{"show":["$\\int_0^{\\infty}xe^{-x}\\,dx$、$\\int_0^{\\infty}x^2e^{-x}\\,dx$、…"],"note":"每一個都要分部積分好幾次。","say":"x 乘 e 的負 x 次方、x 平方乘 e 的負 x 次方，這一整族積分，每一個都要分部積分好幾次。","t":[0,8568]},{"show":["$\\Gamma(s)=\\int_0^{\\infty}x^{s-1}e^{-x}\\,dx$"],"note":"把它們統一成一個函數。","say":"Gamma 函數把這一整族統一成一個函數。看到這種形狀，就不用再算，直接讀值。","t":[8568,16944]},{"show":["$s=2$：$\\int_0^{\\infty}xe^{-x}\\,dx$"],"fig":{"use":0,"to":2},"say":"看圖：s 等於二，曲線是 x 乘 e 的負 x 次方，塗色的面積就是 Gamma 在二的值。","t":[16944,24960]},{"show":["$s=3$：$\\int_0^{\\infty}x^2e^{-x}\\,dx$"],"fig":{"use":0,"to":3},"say":"s 調到三，曲線換成 x 平方乘 e 的負 x 次方，面積跟著變。","t":[24960,31176]}],"drag":{"use":0,"ask":"自己把 $s$ 拉回 $1$ 附近，看曲線變成 $e^{-x}$","range":[1,1.05]}},{"title":"什麼時候收斂","beats":[{"show":["$x\\to\\infty$：$e^{-x}$ 贏"],"note":"指數衰減比任何次方增長都快。","say":"兩端都要檢查。無限遠那端，e 的負 x 次方衰減得比任何次方都快，尾巴一定收斂。","t":[31176,40080]},{"show":["$x\\to 0^+$：像 $x^{s-1}$"],"note":"$e^{-x}\\to 1$。","say":"零那端，e 的負 x 次方趨近一，被積函數就像 x 的 s 減一次方。","t":[40080,46392]},{"show":["$p$ 判別：$s-1>-1$，即 $s>0$"],"note":"此積分表示式在 $s>0$ 時收斂。","say":"用 p 判別，s 減一要大於負一，也就是 s 大於零，這個積分才收斂。","t":[46392,53208]}],"check":2},{"title":"起點與遞迴","beats":[{"show":["$\\Gamma(1)=\\int_0^{\\infty}e^{-x}\\,dx=1$"],"fig":{"use":0,"to":1},"say":"s 等於一，x 的零次方是一，只剩 e 的負 x 次方，面積剛好是一。","t":[53208,59928]},{"show":["$\\Gamma(s+1)$：$u=x^s$，$dv=e^{-x}\\,dx$"],"say":"遞迴從分部積分來：u 取 x 的 s 次方，dv 取 e 的負 x 次方 dx。","t":[59928,66432]},{"show":["邊界項 $\\left[-x^se^{-x}\\right]_0^{\\infty}=0$"],"note":"$\\infty$ 端 $e^{-x}$ 贏；$0$ 端 $x^s=0$。","say":"邊界項兩端都是零：無限遠那邊指數贏，零那邊 x 的 s 次方是零。","t":[66432,73296]},{"show":["$\\Gamma(s+1)=s\\Gamma(s)$"],"say":"剩下 s 乘 Gamma s。這個係數 s 是分部積分生出來的。","t":[73296,79416]}],"check":3},{"title":"整數點是階乘","beats":[{"show":["$\\Gamma(2)=1$，$\\Gamma(3)=2$"],"fig":{"use":0,"to":3},"say":"從 Gamma 一等於一往上推：Gamma 二是一乘一，Gamma 三是二乘一，等於二。","t":[79416,86448]},{"show":["$\\Gamma(4)=6$"],"fig":{"use":0,"to":4},"say":"s 拉到四，面積是六，就是三的階乘。","t":[86448,90888]},{"show":["$\\Gamma(n+1)=n!$"],"note":"差一：$\\Gamma(n)=(n-1)!$，不是 $n!$。","say":"一般來說 Gamma n 加一是 n 階乘。小心差一：Gamma 六是一百二十，不是七百二十。","t":[90888,99504]}],"check":0},{"title":"讀積分","beats":[{"show":["$\\int_0^{\\infty}x^ke^{-x}\\,dx=\\Gamma(k+1)$"],"say":"看到 x 的 k 次方乘 e 的負 x 次方，就是 Gamma k 加一。","t":[99504,104688]},{"show":["$\\int_0^{\\infty}x^2e^{-x}\\,dx=\\Gamma(3)=2$"],"note":"分部積分兩次也會得到 $2$，但要寫半頁。","say":"x 平方那一題，k 是二，直接讀成 Gamma 三，等於二。","t":[104688,110328]},{"show":["$\\int_0^{\\infty}x^ke^{-ax}\\,dx=\\frac{\\Gamma(k+1)}{a^{k+1}}$"],"note":"換元 $u=ax$。","say":"指數裡有常數 a，令 u 等於 a x，多出 a 的 k 加一次方在分母。","t":[110328,116640]},{"show":["$\\int_0^{\\infty}x^4e^{-3x}\\,dx=\\frac{24}{243}=\\frac{8}{81}$"],"say":"例如 x 四次方乘 e 的負三 x 次方：Gamma 五是二十四，除以三的五次方，得八十一分之八。","t":[116640,125304]}],"check":1},{"title":"先換元","beats":[{"show":["$\\int_0^{\\infty}x^3e^{-x^2}\\,dx$"],"note":"指數是 $-x^2$，不是標準形狀。","say":"這一題指數是負 x 平方，不是標準形狀，要先換元。","t":[125304,130944]},{"show":["$u=x^2$，$du=2x\\,dx$"],"note":"$x^3\\,dx=x^2\\cdot x\\,dx=u\\cdot\\frac{du}{2}$","say":"令 u 等於 x 平方。把 x 三次方 dx 拆成 x 平方乘 x dx，就是 u 乘二分之 du。","t":[130944,139368]}],"predict":{"ask":"積分變成？","options":[{"label":"$\\frac{1}{2}\\Gamma(2)=\\frac{1}{2}$","correct":true},{"label":"$\\Gamma(2)=1$","why":"漏了 $du=2x\\,dx$ 留下的 $\\frac{1}{2}$。"},{"label":"$\\frac{1}{2}\\Gamma(4)=3$","why":"換元後被積函數是 $ue^{-u}$，是 $\\Gamma(2)$；$x^3$ 已經拆成 $u$ 和 $x\\,dx$。"}]}}],"checks":[{"ask":"$\\Gamma(5)$ 是多少？","options":[{"label":"$24$","correct":true},{"label":"$120$","why":"那是 $5!=\\Gamma(6)$。$\\Gamma(5)=4!=24$。"},{"label":"$5$","why":"$\\Gamma$ 不是把參數直接拿出來，是階乘。"}]},{"ask":"$\\int_0^{\\infty}x^3e^{-x}\\,dx$ 是？","options":[{"label":"$6$","correct":true},{"label":"$24$","why":"$x^3$ 對應 $\\Gamma(4)=3!=6$，不是 $4!$。"},{"label":"$3$","why":"那只是指數，還要做階乘。"}]},{"ask":"積分 $\\int_0^{\\infty}x^{s-1}e^{-x}\\,dx$ 為什麼要 $s>0$ 才收斂？","options":[{"label":"$x\\to 0$ 時被積函數像 $x^{s-1}$，$s\\le 0$ 時那一端發散","correct":true},{"label":"因為 $e^{-x}$ 在 $s\\le 0$ 時不收斂","why":"$e^{-x}$ 跟 $s$ 無關，問題出在 $x\\to 0$ 那一端。"},{"label":"因為負數沒有階乘","why":"這是結果不是原因；限制來自積分收斂。"}]},{"ask":"$\\Gamma(s+1)=s\\Gamma(s)$ 是用什麼推出來的？","options":[{"label":"分部積分，而且邊界項是 0","correct":true},{"label":"換元 $u=x+1$","why":"遞迴來自分部積分，不是平移。"},{"label":"定義直接代入","why":"定義裡沒有 $s$ 這個係數，要靠分部積分「生出來」。"}]}],"practice":[{"id":"mob-gamma-001","core":true},{"id":"mob-gamma-008","core":true},{"id":"mob-gamma-005","core":true},{"id":"mob-gamma-006","core":true},{"id":"depth-int-026","core":true},{"id":"int-040","core":true},{"id":"rel-adv-011"},{"id":"world-079","challenge":true,"note":"挑戰：令 $x=e^{-t}$，看出是 $-\\Gamma(4)$。"}]},"gamma-recurrence-apps":{"id":"gamma-recurrence-apps","prerequisites":["gamma-definition","u-sub-definite","improper-singular"],"next":["gamma-half"],"related":["reduction-formula","holomorphic"],"objectives":["用 $\\Gamma(s+1)=s\\Gamma(s)$ 處理非整數：把 $\\Gamma(s+n)$ 寫成 $s(s+1)\\cdots(s+n-1)\\Gamma(s)$，算 Gamma 的比值。","用 $x=e^{-t}$ 把 $\\int_0^1x^m(\\ln x)^n\\,dx$ 變成 Gamma 積分，直接得到 $\\frac{(-1)^nn!}{(m+1)^{n+1}}$。","用 $\\Gamma(s)=\\frac{\\Gamma(s+1)}{s}$ 把 Gamma 往左推到負的非整數，並判斷正負號。"],"concept":[{"heading":"① 遞迴不只用在整數","body":["〈Gamma 函數：定義與遞迴〉的 $\\Gamma(s+1)=s\\Gamma(s)$ 對所有 $s>0$ 都成立，不只整數。連用 $n$ 次：","所以 Gamma 的比值永遠可以化成一串乘法：$\\frac{\\Gamma(7/2)}{\\Gamma(3/2)}=\\frac{5}{2}\\cdot\\frac{3}{2}=\\frac{15}{4}$，不需要知道 $\\Gamma\\left(\\frac{3}{2}\\right)$ 本身是多少。"],"tex":["\\Gamma(s+n)=(s+n-1)(s+n-2)\\cdots(s+1)\\,s\\,\\Gamma(s)"]},{"heading":"② 對數的次方：令 $x=e^{-t}$","body":["$\\int_0^1x^m(\\ln x)^n\\,dx$ 看起來跟 Gamma 無關。令 $x=e^{-t}$：$\\ln x=-t$，$dx=-e^{-t}\\,dt$，$x$ 從 $0$ 到 $1$ 對應 $t$ 從 $\\infty$ 到 $0$。","$x^m\\,dx=-e^{-(m+1)t}\\,dt$，把上下限翻回來吃掉負號，積分變成 $(-1)^n\\int_0^{\\infty}t^ne^{-(m+1)t}\\,dt=\\frac{(-1)^n\\Gamma(n+1)}{(m+1)^{n+1}}$（$m>-1$）。","這等於把〈遞迴公式〉裡 $n$ 次分部積分一口氣做完。"],"tex":["\\int_0^1 x^{m}(\\ln x)^{n}\\,dx=\\frac{(-1)^{n}\\,n!}{(m+1)^{n+1}}\\qquad(m>-1)"]},{"heading":"③ 往左推：負的非整數","body":["積分定義只在 $s>0$ 收斂，但遞迴倒過來寫 $\\Gamma(s)=\\frac{\\Gamma(s+1)}{s}$ 的右邊在 $-1<s<0$ 時有意義（$s+1>0$）。用它定義 $\\Gamma(s)$，再一步一步推到 $(-2,-1)$、$(-3,-2)$……","正負號：$-1<s<0$ 時 $\\Gamma(s+1)>0$、$s<0$，所以 $\\Gamma(s)<0$；再往左一段又變正，交替變號。$s=0,-1,-2,\\dots$ 時要除以 $0$，$\\Gamma$ 在這些點沒有定義（函數值往 $\\pm\\infty$ 衝）。"]},{"heading":"為什麼往左推是「唯一合理」的延伸","body":["這個延伸跟積分定義在 $s>0$ 吻合，而且保持 $\\Gamma(s+1)=s\\Gamma(s)$ 對所有非整數的 $s$ 成立。複變裡可以證明：在去掉 $0,-1,-2,\\dots$ 的複平面上，只有一個全純函數（〈全純函數〉）跟 $s>0$ 的 Gamma 一致，所以這個延伸是唯一的。這叫解析延拓。"],"collapsible":true}],"workedExamples":[{"title":"非整數的比值","prompt":"$\\frac{\\Gamma(7/2)}{\\Gamma(3/2)}$","steps":["$\\Gamma\\left(\\frac{7}{2}\\right)=\\frac{5}{2}\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{5}{2}\\cdot\\frac{3}{2}\\Gamma\\left(\\frac{3}{2}\\right)$。","$\\Gamma\\left(\\frac{3}{2}\\right)$ 約掉：比值 $=\\frac{5}{2}\\cdot\\frac{3}{2}=\\frac{15}{4}$。","換成積分的語言：$\\int_0^{\\infty}x^{5/2}e^{-x}\\,dx$ 是 $\\int_0^{\\infty}x^{1/2}e^{-x}\\,dx$ 的 $\\frac{15}{4}$ 倍。"],"answer":"$\\frac{15}{4}$"},{"title":"對數次方變 Gamma","prompt":"$\\int_0^1x^3(\\ln x)^2\\,dx$","problemId":"rel-hard-int-004","steps":["令 $x=e^{-t}$：$x^3=e^{-3t}$，$(\\ln x)^2=t^2$，$dx=-e^{-t}\\,dt$，上下限 $x:0\\to 1$ 變成 $t:\\infty\\to 0$。","積分 $=\\int_{\\infty}^0e^{-3t}t^2(-e^{-t})\\,dt=\\int_0^{\\infty}t^2e^{-4t}\\,dt$。","這是 $\\frac{\\Gamma(3)}{4^3}=\\frac{2}{64}=\\frac{1}{32}$（指數有常數 $4$：用〈Gamma 函數：定義與遞迴〉的 $\\int_0^{\\infty}x^ke^{-ax}\\,dx=\\frac{\\Gamma(k+1)}{a^{k+1}}$）。","符號檢查：被積函數 $\\ge 0$，答案正，合理。"],"answer":"$\\frac{1}{32}$"},{"title":"用一個不知道值的 Gamma 表示另一個","prompt":"把 $\\Gamma\\left(\\frac{10}{3}\\right)$ 寫成 $\\Gamma\\left(\\frac{1}{3}\\right)$ 的倍數。","steps":["$\\frac{10}{3}=\\frac{1}{3}+3$，連用三次遞迴。","$\\Gamma\\left(\\frac{10}{3}\\right)=\\frac{7}{3}\\Gamma\\left(\\frac{7}{3}\\right)=\\frac{7}{3}\\cdot\\frac{4}{3}\\Gamma\\left(\\frac{4}{3}\\right)=\\frac{7}{3}\\cdot\\frac{4}{3}\\cdot\\frac{1}{3}\\Gamma\\left(\\frac{1}{3}\\right)$。","$\\frac{7\\cdot 4\\cdot 1}{3\\cdot 3\\cdot 3}=\\frac{28}{27}$，所以 $\\Gamma\\left(\\frac{10}{3}\\right)=\\frac{28}{27}\\Gamma\\left(\\frac{1}{3}\\right)$。$\\Gamma\\left(\\frac{1}{3}\\right)\\approx 2.6789$ 沒有簡單的閉式，但比值是精確的。"],"answer":"$\\Gamma\\left(\\frac{10}{3}\\right)=\\frac{28}{27}\\Gamma\\left(\\frac{1}{3}\\right)$"}],"pitfalls":["遞迴往上推時乘錯數：$\\Gamma\\left(\\frac{9}{2}\\right)=\\frac{7}{2}\\Gamma\\left(\\frac{7}{2}\\right)$，乘的是 $s$，不是 $s+1$。","$x=e^{-t}$ 換元時漏了 $dx=-e^{-t}\\,dt$ 帶來的那一個 $e^{-t}$，分母變成 $m^{n+1}$ 而不是 $(m+1)^{n+1}$。","忘了 $(\\ln x)^n$ 在 $n$ 為奇數時是負的，答案少了負號。","以為 $\\Gamma$ 在負數全都沒有定義；只有 $0$、$-1$、$-2$、…… 沒有定義。"],"voice":"7e9a809b","sections":[{"title":"遞迴不只用在整數","beats":[{"show":["$\\Gamma(s+1)=s\\Gamma(s)$，所有 $s>0$"],"say":"Gamma 的遞迴對所有大於零的 s 都成立，不只整數。","t":[0,4992]},{"show":["$\\Gamma(s+n)=(s+n-1)\\cdots(s+1)\\,s\\,\\Gamma(s)$"],"note":"連用 $n$ 次。","say":"連續用 n 次，Gamma s 加 n 就是一串因子乘上 Gamma s。乘的是 s，不是 s 加一。","t":[4992,13248]},{"show":["$\\frac{\\Gamma(7/2)}{\\Gamma(3/2)}=\\frac{5}{2}\\cdot\\frac{3}{2}=\\frac{15}{4}$"],"note":"不需要知道 $\\Gamma\\left(\\frac{3}{2}\\right)$ 是多少。","say":"所以 Gamma 的比值永遠化成乘法：二分之七往下推兩步，乘二分之五、二分之三，得四分之十五。","t":[13248,22536]}],"check":0},{"title":"不知道值也能比","beats":[{"show":["$\\Gamma\\left(\\frac{10}{3}\\right)$ 寫成 $\\Gamma\\left(\\frac{1}{3}\\right)$ 的倍數"],"note":"$\\frac{10}{3}=\\frac{1}{3}+3$","say":"三分之十比三分之一多三，所以連用三次遞迴。","t":[22536,27744]},{"show":["$\\frac{7}{3}\\cdot\\frac{4}{3}\\cdot\\frac{1}{3}\\,\\Gamma\\left(\\frac{1}{3}\\right)$"],"say":"往下推：先乘三分之七，再乘三分之四，最後乘三分之一。","t":[27744,34296]}],"predict":{"ask":"$\\Gamma\\left(\\frac{10}{3}\\right)$ 是 $\\Gamma\\left(\\frac{1}{3}\\right)$ 的幾倍？","options":[{"label":"$\\frac{28}{27}$","correct":true},{"label":"$\\frac{28}{9}$","why":"少乘了最後一個 $\\frac{1}{3}$：$\\Gamma\\left(\\frac{4}{3}\\right)=\\frac{1}{3}\\Gamma\\left(\\frac{1}{3}\\right)$。"},{"label":"$\\frac{10}{3}\\cdot\\frac{7}{3}\\cdot\\frac{4}{3}$","why":"乘的是 $s$ 不是 $s+1$：$\\Gamma\\left(\\frac{10}{3}\\right)=\\frac{7}{3}\\Gamma\\left(\\frac{7}{3}\\right)$。"}]}},{"title":"對數次方","beats":[{"show":["$\\int_0^1x^m(\\ln x)^n\\,dx$"],"note":"看起來跟 Gamma 無關。","say":"x 的 m 次方乘自然對數 x 的 n 次方，從零積到一，看起來跟 Gamma 沒關係。","t":[34296,41400]},{"show":["令 $x=e^{-t}$：$\\ln x=-t$"],"note":"$dx=-e^{-t}\\,dt$；$x:0\\to 1$ 對應 $t:\\infty\\to 0$。","say":"令 x 等於 e 的負 t 次方，自然對數就變成負 t。x 從零到一，t 從無限大回到零。","t":[41400,50136]},{"show":["$x^m\\,dx=-e^{-(m+1)t}\\,dt$"],"note":"$dx$ 帶來的 $e^{-t}$ 讓指數多一個 $1$。","say":"注意 dx 也帶著一個 e 的負 t 次方，所以指數是 m 加一，不是 m。上下限翻回來吃掉負號。","t":[50136,59376]}],"check":3},{"title":"算一題","beats":[{"show":["$\\int_0^1x^3(\\ln x)^2\\,dx=\\int_0^{\\infty}t^2e^{-4t}\\,dt$"],"note":"$m=3$，指數是 $m+1=4$。","say":"x 三次方乘自然對數平方：換元之後，指數是三加一等於四。","t":[59376,65904]},{"show":["$=\\frac{\\Gamma(3)}{4^3}=\\frac{2}{64}=\\frac{1}{32}$"],"say":"用指數有常數的公式：Gamma 三是二，除以四的三次方，得三十二分之一。","t":[65904,73296]},{"show":["$\\frac{(-1)^n\\,n!}{(m+1)^{n+1}}$"],"note":"$n$ 是奇數時答案是負的。","say":"一般公式是這樣。n 是偶數，答案是正的；n 是奇數，自然對數的奇次方是負的，答案帶負號。","t":[73296,83448]}],"check":1},{"title":"往左推","beats":[{"show":["$\\Gamma(s)=\\frac{\\Gamma(s+1)}{s}$"],"note":"$-1<s<0$ 時右邊有意義。","say":"積分只在 s 大於零收斂。把遞迴倒過來寫，s 在負一和零之間，右邊還是有意義。","t":[83448,92016]},{"show":["$-1<s<0$：$\\Gamma(s)<0$"],"note":"$\\Gamma(s+1)>0$，$s<0$。","say":"分子是正的，分母 s 是負的，所以這一段 Gamma 是負的。再往左一段又變正，交替變號。","t":[92016,101112]},{"show":["$s=0,-1,-2,\\dots$ 沒有定義"],"note":"要除以 $0$，函數值往 $\\pm\\infty$ 衝。","say":"可是在零、負一、負二這些點要除以零，Gamma 沒有定義，函數值往正負無限大衝。","t":[101112,109224]}],"check":2}],"checks":[{"ask":"$\\frac{\\Gamma(9/2)}{\\Gamma(5/2)}$ 是？","options":[{"label":"$\\frac{35}{4}$","correct":true},{"label":"$\\frac{63}{4}$","why":"乘錯了：$\\Gamma\\left(\\frac{9}{2}\\right)=\\frac{7}{2}\\Gamma\\left(\\frac{7}{2}\\right)$、$\\Gamma\\left(\\frac{7}{2}\\right)=\\frac{5}{2}\\Gamma\\left(\\frac{5}{2}\\right)$，乘的是 $\\frac{7}{2}$ 和 $\\frac{5}{2}$，不是 $\\frac{9}{2}$ 和 $\\frac{7}{2}$。"},{"label":"$2$","why":"Gamma 的比值不是參數相減；要把遞迴的因子乘起來。"}]},{"ask":"$\\int_0^1x(\\ln x)^2\\,dx$ 是？","options":[{"label":"$\\frac{1}{4}$","correct":true},{"label":"$\\frac{1}{8}$","why":"公式是 $\\frac{n!}{(m+1)^{n+1}}=\\frac{2!}{2^3}=\\frac{2}{8}$；漏了 $2!=2$。"},{"label":"$-\\frac{1}{4}$","why":"$(\\ln x)^2\\ge 0$，積分是正的；負號只在 $n$ 是奇數時出現。"}]},{"ask":"$-1<s<0$ 時，$\\Gamma(s)$ 的正負是？","options":[{"label":"負的","correct":true},{"label":"正的","why":"$\\Gamma(s)=\\frac{\\Gamma(s+1)}{s}$，$\\Gamma(s+1)>0$ 但 $s<0$，所以是負的。"},{"label":"沒有定義","why":"積分定義不收斂，但用 $\\Gamma(s)=\\frac{\\Gamma(s+1)}{s}$ 可以定義；只有 $0$、$-1$、$-2$、…… 沒有定義。"}]},{"ask":"令 $x=e^{-t}$，$\\int_0^1x^m(-\\ln x)^n\\,dx$ 變成？","options":[{"label":"$\\int_0^{\\infty}t^ne^{-(m+1)t}\\,dt$","correct":true},{"label":"$\\int_0^{\\infty}t^ne^{-mt}\\,dt$","why":"漏了 $dx=-e^{-t}\\,dt$ 裡的 $e^{-t}$，它讓指數多一個 $1$。"},{"label":"$\\int_0^1t^ne^{-(m+1)t}\\,dt$","why":"$x$ 從 $0$ 到 $1$ 時 $t=-\\ln x$ 從 $\\infty$ 到 $0$，區間變成 $[0,\\infty)$。"}]}],"practice":[{"id":"burst-rec-007","core":true},{"id":"burst-int-004","core":true},{"id":"rel-hard-int-004","core":true},{"id":"burst-int-005","core":true},{"id":"burst-int-006","core":true},{"id":"burst-rec-002"},{"id":"burst-boss-int-012"},{"id":"burst-boss-int-013"},{"id":"burst-boss-param-006","challenge":true,"note":"挑戰：答案要寫成 $n$ 的式子：$-\\frac{6}{(n+1)^4}$。"}]},"gamma-half":{"id":"gamma-half","prerequisites":["gamma-recurrence-apps","polar-double-integral","improper-infinite","u-sub-definite"],"next":["gamma-half-integer"],"related":["gaussian-integral","beta-gamma-relation"],"objectives":["用換元 $x=u^2$ 把 $\\Gamma\\left(\\frac{1}{2}\\right)$ 變成 $2\\int_0^{\\infty}e^{-u^2}\\,du$。","用「平方之後換極座標」算出 $\\int_0^{\\infty}e^{-u^2}\\,du=\\frac{\\sqrt{\\pi}}{2}$，並說得出多出來的 $r$ 為什麼是關鍵。","用縮放算 $\\int_0^{\\infty}e^{-ax^2}\\,dx=\\frac{1}{2}\\sqrt{\\frac{\\pi}{a}}$。"],"concept":[{"heading":"① 從 Gamma 到鐘形曲線","body":["$\\Gamma\\left(\\frac{1}{2}\\right)=\\int_0^{\\infty}x^{-1/2}e^{-x}\\,dx$。令 $x=u^2$（$u\\ge 0$），$dx=2u\\,du$，$x^{-1/2}=\\frac{1}{u}$：","$\\Gamma\\left(\\frac{1}{2}\\right)=\\int_0^{\\infty}\\frac{1}{u}e^{-u^2}\\,2u\\,du=2\\int_0^{\\infty}e^{-u^2}\\,du$。","問題變成鐘形曲線 $e^{-u^2}$ 底下的面積。$e^{-u^2}$ 有反導函數，但寫不成常見初等函數的有限組合，所以要換個方法。"]},{"heading":"② 一維算不動，就算它的平方","body":["令 $I=\\int_0^{\\infty}e^{-x^2}\\,dx$。$I^2$ 是兩個一樣的積分相乘，可以寫成第一象限上的二重積分：$I^2=\\int_0^{\\infty}\\int_0^{\\infty}e^{-(x^2+y^2)}\\,dx\\,dy$。","被積函數只跟 $x^2+y^2=r^2$ 有關，換極座標：第一象限是 $0\\le\\theta\\le\\frac{\\pi}{2}$、$0\\le r<\\infty$，面積元素 $dx\\,dy=r\\,dr\\,d\\theta$（〈極座標二重積分〉）。","多出來的 $r$ 是關鍵：$\\int e^{-r^2}r\\,dr$ 用 $u=r^2$ 一行就積出來。"],"tex":["I^{2}=\\int_0^{\\pi/2}\\!\\!\\int_0^{\\infty}e^{-r^{2}}\\,r\\,dr\\,d\\theta=\\frac{\\pi}{2}\\cdot\\frac12=\\frac{\\pi}{4}"]},{"heading":"③ 結果","body":["$I>0$，所以 $I=\\frac{\\sqrt{\\pi}}{2}$，$\\Gamma\\left(\\frac{1}{2}\\right)=2I=\\sqrt{\\pi}$。由對稱，$\\int_{-\\infty}^{\\infty}e^{-x^2}\\,dx=\\sqrt{\\pi}$。","一個 $\\pi$ 出現在沒有圓的積分裡，是因為平方之後的被積函數 $e^{-(x^2+y^2)}$ 有旋轉對稱，圓是藏在裡面的。"]},{"heading":"這個計算為什麼嚴格","body":["$I^2=\\left(\\int_0^{\\infty}e^{-x^2}\\,dx\\right)^2$ 寫成整個第一象限的二重積分，需要先在有限區域上做、再取極限。令 $S_R=[0,R]^2$，$D_R$ 是半徑 $R$ 的四分之一圓盤。被積函數為正，而且 $D_R\\subset S_R\\subset D_{R\\sqrt{2}}$，所以","$\\iint_{D_R}\\le\\left(\\int_0^Re^{-x^2}\\,dx\\right)^2\\le\\iint_{D_{R\\sqrt{2}}}$。左右兩邊用極座標算出來是 $\\frac{\\pi}{4}(1-e^{-R^2})$ 與 $\\frac{\\pi}{4}(1-e^{-2R^2})$，$R\\to\\infty$ 都 $\\to\\frac{\\pi}{4}$，夾擠得 $I^2=\\frac{\\pi}{4}$。"],"collapsible":true}],"workedExamples":[{"title":"完整推導","prompt":"證明 $\\Gamma\\left(\\frac{1}{2}\\right)=\\sqrt{\\pi}$。","problemId":"mob-gamma-002","steps":["$x=u^2$：$\\Gamma\\left(\\frac{1}{2}\\right)=2\\int_0^{\\infty}e^{-u^2}\\,du=2I$。","$I^2=\\int_0^{\\pi/2}\\int_0^{\\infty}e^{-r^2}r\\,dr\\,d\\theta$。","內層：$\\int_0^{\\infty}e^{-r^2}r\\,dr=\\left[-\\frac{e^{-r^2}}{2}\\right]_0^{\\infty}=\\frac{1}{2}$。外層乘上 $\\theta$ 的範圍 $\\frac{\\pi}{2}$：$I^2=\\frac{\\pi}{4}$。","$I=\\frac{\\sqrt{\\pi}}{2}$（取正根，因為被積函數為正），$\\Gamma\\left(\\frac{1}{2}\\right)=\\sqrt{\\pi}\\approx 1.7725$。"],"answer":"$\\sqrt{\\pi}$"},{"title":"指數有係數","prompt":"$\\int_0^{\\infty}e^{-3x^2}\\,dx$","steps":["令 $u=\\sqrt{3}\\,x$，$dx=\\frac{du}{\\sqrt{3}}$，$3x^2=u^2$。","積分 $=\\frac{1}{\\sqrt{3}}\\int_0^{\\infty}e^{-u^2}\\,du=\\frac{1}{\\sqrt{3}}\\cdot\\frac{\\sqrt{\\pi}}{2}$。","一般公式：$\\int_0^{\\infty}e^{-ax^2}\\,dx=\\frac{1}{2}\\sqrt{\\frac{\\pi}{a}}$，$a>0$。這裡 $a=3$，得 $\\frac{1}{2}\\sqrt{\\frac{\\pi}{3}}\\approx 0.5117$。"],"answer":"$\\frac{1}{2}\\sqrt{\\frac{\\pi}{3}}$"},{"title":"常態分布的常數","prompt":"$\\int_{-\\infty}^{\\infty}e^{-x^2/2}\\,dx$","steps":["用上面的公式，$a=\\frac{1}{2}$：$\\int_0^{\\infty}e^{-x^2/2}\\,dx=\\frac{1}{2}\\sqrt{\\frac{\\pi}{1/2}}=\\frac{1}{2}\\sqrt{2\\pi}$。","被積函數是偶函數，整條實數線是兩倍：$\\sqrt{2\\pi}$。","這就是常態分布密度前面為什麼是 $\\frac{1}{\\sqrt{2\\pi}}$：讓總面積等於 $1$。"],"answer":"$\\sqrt{2\\pi}$"}],"pitfalls":["換元 $x=u^2$ 時漏了 $dx=2u\\,du$ 的 $2$，得到 $\\Gamma\\left(\\frac{1}{2}\\right)=\\frac{\\sqrt{\\pi}}{2}$。","極座標忘了 $r$：沒有 $r$，$\\int e^{-r^2}\\,dr$ 一樣積不出來。","$\\theta$ 的範圍：只算第一象限是 $\\frac{\\pi}{2}$；整個平面才是 $2\\pi$（那時得到的是 $\\left(\\int_{-\\infty}^{\\infty}\\right)^2=\\pi$）。","$\\int_0^{\\infty}$ 與 $\\int_{-\\infty}^{\\infty}$ 混用，差一個 $2$。"],"voice":"fb85672c","sections":[{"title":"變成鐘形曲線","beats":[{"show":["$\\Gamma\\left(\\frac{1}{2}\\right)=\\int_0^{\\infty}x^{-1/2}e^{-x}\\,dx$"],"say":"Gamma 在二分之一的值，是 x 的負二分之一次方乘 e 的負 x 次方，從零積到無限大。","t":[0,7800]},{"show":["令 $x=u^2$，$dx=2u\\,du$"],"note":"$u\\ge 0$，$x^{-1/2}=\\frac{1}{u}$。","say":"令 x 等於 u 平方，dx 是二 u du，x 的負二分之一次方變成 u 分之一。","t":[7800,14808]}],"predict":{"ask":"$\\Gamma\\left(\\frac{1}{2}\\right)$ 變成？","options":[{"label":"$2\\int_0^{\\infty}e^{-u^2}\\,du$","correct":true},{"label":"$\\int_0^{\\infty}e^{-u^2}\\,du$","why":"$\\frac{1}{u}$ 和 $2u$ 的 $u$ 約掉了，但 $2$ 還在。"},{"label":"$\\int_0^{\\infty}\\frac{1}{u}e^{-u^2}\\,du$","why":"漏了 $dx=2u\\,du$；換元時 $dx$ 也要換。"}]}},{"title":"算它的平方","beats":[{"show":["$e^{-u^2}$：寫不成初等函數的組合"],"note":"鐘形曲線底下的面積，要換個方法。","say":"問題變成鐘形曲線底下的面積。它的反導函數寫不成常見的初等函數，直接積算不動。","t":[14808,24000]},{"show":["$I^2=\\int_0^{\\infty}\\int_0^{\\infty}e^{-(x^2+y^2)}\\,dx\\,dy$"],"note":"$I=\\int_0^{\\infty}e^{-x^2}\\,dx$","say":"一維算不動，就算它的平方：兩個一樣的積分相乘，寫成第一象限上的二重積分。","t":[24000,31896]},{"show":["換極座標：$dx\\,dy=r\\,dr\\,d\\theta$"],"note":"$0\\le\\theta\\le\\frac{\\pi}{2}$，$0\\le r<\\infty$。","say":"被積函數只跟 x 平方加 y 平方有關，也就是 r 平方，所以換極座標，面積元素多一個 r。","t":[31896,40608]},{"show":["$\\int_0^{\\infty}e^{-r^2}r\\,dr=\\frac{1}{2}$"],"note":"令 $u=r^2$，一行積完。","say":"多出來的 r 是關鍵：令 u 等於 r 平方，一行就積出二分之一。完整的極限論證在後面那節。","t":[40608,50112]}],"check":2},{"title":"結果","beats":[{"show":["$I^2=\\frac{\\pi}{2}\\cdot\\frac{1}{2}=\\frac{\\pi}{4}$"],"note":"外層乘上 $\\theta$ 的範圍 $\\frac{\\pi}{2}$。","say":"內層是二分之一，外層乘上角度的範圍二分之 pi，I 平方等於四分之 pi。","t":[50112,57336]},{"show":["$I=\\frac{\\sqrt{\\pi}}{2}$"],"note":"取正根：被積函數為正。","say":"被積函數是正的，取正根，I 是二分之根號 pi。","t":[57336,62568]},{"show":["$\\Gamma\\left(\\frac{1}{2}\\right)=2I=\\sqrt{\\pi}\\approx 1.7725$"],"say":"Gamma 二分之一是兩倍的 I，就是根號 pi。一個沒有圓的積分冒出 pi，因為平方之後有旋轉對稱。","t":[62568,72168]}],"check":0},{"title":"證明：為什麼嚴格","proof":true,"of":3,"skeleton":"夾擠","beats":[{"show":["有限區域上算，再用兩個圓盤夾"],"note":"$S_R=[0,R]^2$；$D_R$：半徑 $R$ 的四分之一圓盤。","say":"策略：無窮的第一象限不能直接換座標。先在有限的正方形上算，再用兩個四分之一圓盤把它夾住。","t":[72168,82368]},{"show":["$D_R\\subset S_R\\subset D_{R\\sqrt{2}}$"],"note":"正方形最遠的角 $(R,R)$ 離原點 $R\\sqrt{2}$。","why":{"ask":"為什麼 $S_R\\subset D_{R\\sqrt{2}}$？","say":"正方形為什麼裝得進半徑 R 根號二的圓盤？","options":[{"label":"最遠的角 $(R,R)$ 離原點 $R\\sqrt{2}$","correct":true},{"label":"正方形面積 $R^2$ 比較小","why":"面積小不代表裝得進去；要每一點離原點都不超過 $R\\sqrt{2}$。"},{"label":"邊長 $R$ 小於 $R\\sqrt{2}$","why":"邊長只管到軸上的點；離原點最遠的是對角的角。"}],"t":[82368,86784]},"say":"正方形裡離原點最遠的是對角那個角，距離 R 根號二，所以整個正方形都在大圓盤裡。","t":[86784,95136]},{"show":["$\\iint_{D_R}\\le\\left(\\int_0^Re^{-x^2}dx\\right)^2$","$\\le\\iint_{D_{R\\sqrt{2}}}$"],"note":"被積函數為正：區域大，積分大。","say":"被積函數是正的，區域越大積分越大，正方形上的積分就被兩個圓盤上的積分夾住。","t":[95136,103200]},{"show":["$\\frac{\\pi}{4}(1-e^{-R^2})$ 與 $\\frac{\\pi}{4}(1-e^{-2R^2})$"],"note":"極座標。","say":"圓盤用極座標算：左邊四分之 pi 乘一減 e 的負 R 平方次方，右邊的 R 平方換成二 R 平方。","t":[103200,111576]},{"show":["$R\\to\\infty$：兩邊都 $\\to\\frac{\\pi}{4}$ ⇒ $I^2=\\frac{\\pi}{4}$"],"note":"上下界趨近同一個數。","why":{"ask":"為什麼能下結論 $I^2=\\frac{\\pi}{4}$？","say":"R 趨近無限大。憑什麼說 I 平方等於四分之 pi？","options":[{"label":"上下兩邊都 $\\to\\frac{\\pi}{4}$","correct":true},{"label":"右邊 $\\to\\frac{\\pi}{4}$ 就夠了","why":"只有上界，只能說 $I^2\\le\\frac{\\pi}{4}$；還要下界也趨近同一個數。"},{"label":"左邊 $\\to\\frac{\\pi}{4}$ 就夠了","why":"只有下界，只能說 $I^2\\ge\\frac{\\pi}{4}$；兩邊都要。"}],"t":[111576,117240]},"say":"R 趨近無限大，e 的負 R 平方次方趨近零，上下兩邊都趨近四分之 pi，夾擠得 I 平方等於四分之 pi。","t":[117240,126816]}],"where":{"ask":"「被積函數為正」用在哪一步？","steps":[{"label":"$D_R\\subset S_R\\subset D_{R\\sqrt{2}}$","why":"這是純幾何：比的是點到原點的距離。"},{"label":"區域大，積分大：三個積分排大小","correct":true},{"label":"極座標算出 $\\frac{\\pi}{4}(1-e^{-R^2})$","why":"這只用到 $dx\\,dy=r\\,dr\\,d\\theta$ 和 $u=r^2$ 的換元。"},{"label":"$R\\to\\infty$，夾擠","why":"這只用到 $e^{-R^2}\\to0$ 和夾擠定理。"}]}},{"title":"整條實數線","beats":[{"show":["$\\int_{-\\infty}^{\\infty}e^{-x^2}\\,dx=\\sqrt{\\pi}$"],"note":"偶函數，是 $\\int_0^{\\infty}$ 的兩倍。","say":"鐘形曲線左右對稱，整條實數線的面積是兩倍的 I，也是根號 pi。","t":[126816,133440]},{"show":["$\\int_{-\\infty}^{\\infty}e^{-x^2/2}\\,dx=\\sqrt{2\\pi}$"],"say":"指數換成負二分之 x 平方，整條線的面積是根號二 pi。","t":[133440,139224]},{"show":["常態分布前面的 $\\frac{1}{\\sqrt{2\\pi}}$"],"note":"讓總面積等於 $1$。","say":"這就是常態分布的密度前面為什麼有根號二 pi 分之一：讓總面積剛好是一。","t":[139224,146448]}],"check":1},{"title":"指數有係數","beats":[{"show":["$\\int_0^{\\infty}e^{-3x^2}\\,dx$"],"note":"令 $u=\\sqrt{3}\\,x$，$dx=\\frac{du}{\\sqrt{3}}$。","say":"指數前面有係數三，令 u 等於根號三 x，dx 就是根號三分之 du。","t":[146448,153360]},{"show":["$=\\frac{1}{\\sqrt{3}}\\cdot\\frac{\\sqrt{\\pi}}{2}$"],"say":"剩下的是標準的鐘形積分二分之根號 pi，前面多一個根號三分之一。","t":[153360,160128]},{"show":["$\\int_0^{\\infty}e^{-ax^2}\\,dx=\\frac{1}{2}\\sqrt{\\frac{\\pi}{a}}$"],"note":"$a>0$；$a=3$ 時約 $0.5117$。","say":"一般公式：係數 a 讓曲線變窄，面積是二分之一乘根號 a 分之 pi。","t":[160128,166872]}],"check":3}],"checks":[{"ask":"$\\Gamma\\left(\\frac{1}{2}\\right)$ 等於？","options":[{"label":"$\\sqrt{\\pi}$","correct":true},{"label":"$\\pi$","why":"$\\pi$ 是 $I^2$ 那一層的量（整個平面上的 $\\left(\\int_{-\\infty}^{\\infty}e^{-x^2}\\,dx\\right)^2$），開根號才是 $\\sqrt{\\pi}$。"},{"label":"$\\frac{\\sqrt{\\pi}}{2}$","why":"那是 $\\int_0^{\\infty}e^{-x^2}\\,dx$。$\\Gamma\\left(\\frac{1}{2}\\right)=2\\int_0^{\\infty}e^{-u^2}\\,du$，多一個 $2$。"}]},{"ask":"$\\int_{-\\infty}^{\\infty}e^{-x^2}\\,dx$ 等於？","options":[{"label":"$\\sqrt{\\pi}$","correct":true},{"label":"$\\frac{\\sqrt{\\pi}}{2}$","why":"那是從 $0$ 積到 $\\infty$ 的一半。"},{"label":"$\\pi$","why":"$\\pi$ 是它的平方；面積本身要開根號。"}]},{"ask":"換極座標之後為什麼算得出來？","options":[{"label":"面積元素多了一個 $r$，$\\int e^{-r^2}r\\,dr$ 可以用 $u=r^2$ 積出來","correct":true},{"label":"因為 $e^{-r^2}$ 本身有初等反導函數","why":"$e^{-r^2}$ 跟 $e^{-x^2}$ 是同一個函數，一樣沒有初等反導函數；靠的是多出來的 $r$。"},{"label":"因為極座標下積分區域變成有限","why":"$r$ 還是從 $0$ 到 $\\infty$，區域沒有變有限。"}]},{"ask":"$\\int_0^{\\infty}e^{-4x^2}\\,dx$ 等於？","options":[{"label":"$\\frac{\\sqrt{\\pi}}{4}$","correct":true},{"label":"$\\frac{\\sqrt{\\pi}}{8}$","why":"令 $u=2x$，$dx=\\frac{du}{2}$，只除以 $2$，不是 $4$：$\\frac{1}{2}\\cdot\\frac{\\sqrt{\\pi}}{2}=\\frac{\\sqrt{\\pi}}{4}$。"},{"label":"$\\frac{\\sqrt{\\pi}}{2}$","why":"係數 $4$ 會讓曲線變窄、面積變小，不能忽略。"}]}],"practice":[{"id":"mob-gamma-002","core":true},{"id":"world-090","core":true},{"id":"mob-gamma-007"},{"id":"mob-gamma-003"}]},"gamma-half-integer":{"id":"gamma-half-integer","prerequisites":["gamma-half","gamma-recurrence-apps"],"next":["gamma-scaled"],"related":[],"objectives":["從 $\\Gamma\\left(\\frac{1}{2}\\right)=\\sqrt{\\pi}$ 用遞迴算出 $\\Gamma\\left(\\frac{3}{2}\\right)$、$\\Gamma\\left(\\frac{5}{2}\\right)$、$\\Gamma\\left(\\frac{7}{2}\\right)$，並寫出一般式 $\\Gamma\\left(n+\\frac{1}{2}\\right)=\\frac{1\\cdot 3\\cdot 5\\cdots(2n-1)}{2^n}\\cdot\\sqrt{\\pi}$。","往左推出 $\\Gamma\\left(-\\frac{1}{2}\\right)=-2\\sqrt{\\pi}$、$\\Gamma\\left(-\\frac{3}{2}\\right)=\\frac{4\\sqrt{\\pi}}{3}$。","用 $\\int_0^{\\infty}x^me^{-x^2}\\,dx=\\frac{1}{2}\\Gamma\\left(\\frac{m+1}{2}\\right)$ 一次處理所有 $x^me^{-x^2}$：$m$ 奇數得到階乘，$m$ 偶數得到 $\\sqrt{\\pi}$。"],"concept":[{"heading":"① 從 $\\sqrt{\\pi}$ 往上爬","body":["每往上一格，乘上「前一格的參數」：$\\Gamma\\left(\\frac{3}{2}\\right)=\\frac{1}{2}\\Gamma\\left(\\frac{1}{2}\\right)=\\frac{\\sqrt{\\pi}}{2}$；$\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3}{2}\\Gamma\\left(\\frac{3}{2}\\right)=\\frac{3\\sqrt{\\pi}}{4}$；$\\Gamma\\left(\\frac{7}{2}\\right)=\\frac{5}{2}\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{15\\sqrt{\\pi}}{8}$。","一般式：分子是連續奇數的乘積，分母是 $2$ 的次方。也可以寫成 $\\Gamma\\left(n+\\frac{1}{2}\\right)=\\frac{(2n)!}{4^nn!}\\cdot\\sqrt{\\pi}$（分子分母同乘 $2\\cdot 4\\cdots(2n)$）。"],"tex":["\\Gamma\\!\\left(n+\\tfrac12\\right)=\\frac{1\\cdot3\\cdot5\\cdots(2n-1)}{2^{n}}\\sqrt{\\pi}"]},{"heading":"② 往下推到負的半整數","body":["用 $\\Gamma(s)=\\frac{\\Gamma(s+1)}{s}$：$\\Gamma\\left(-\\frac{1}{2}\\right)=\\frac{\\Gamma(1/2)}{-1/2}=-2\\sqrt{\\pi}$；$\\Gamma\\left(-\\frac{3}{2}\\right)=\\frac{\\Gamma(-1/2)}{-3/2}=\\frac{4\\sqrt{\\pi}}{3}$。","往下是「除以」，往上是「乘以」，方向不要搞混。正負號每過一個負整數翻一次。"]},{"heading":"③ 一條公式管所有 $x^me^{-x^2}$","body":["令 $u=x^2$，$x=u^{1/2}$，$dx=\\frac{du}{2\\sqrt{u}}$：$x^m\\,dx=u^{m/2}\\cdot\\frac{du}{2u^{1/2}}=\\frac{1}{2}u^{(m-1)/2}\\,du$。所以 $\\int_0^{\\infty}x^me^{-x^2}\\,dx=\\frac{1}{2}\\Gamma\\left(\\frac{m+1}{2}\\right)$（$m>-1$）。","$m$ 是奇數時 $\\frac{m+1}{2}$ 是整數，答案是階乘的一半，沒有 $\\pi$：例如 $m=3$ 得 $\\frac{1}{2}\\Gamma(2)=\\frac{1}{2}$。$m$ 是偶數時 $\\frac{m+1}{2}$ 是半整數，答案帶 $\\sqrt{\\pi}$：例如 $m=4$ 得 $\\frac{1}{2}\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3\\sqrt{\\pi}}{8}$。","這解釋了一個常見的現象：$x^3e^{-x^2}$ 用換元直接積得出來，$x^4e^{-x^2}$ 卻怎麼分部積分都會剩下一個 Gaussian。"],"tex":["\\int_0^{\\infty}x^{m}e^{-x^{2}}\\,dx=\\frac12\\,\\Gamma\\!\\left(\\frac{m+1}{2}\\right)"]}],"workedExamples":[{"title":"$\\Gamma\\left(\\frac{7}{2}\\right)$","prompt":"$\\Gamma\\left(\\frac{7}{2}\\right)$","problemId":"mob-gamma-009","steps":["$\\Gamma\\left(\\frac{7}{2}\\right)=\\frac{5}{2}\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{5}{2}\\cdot\\frac{3}{2}\\Gamma\\left(\\frac{3}{2}\\right)=\\frac{5}{2}\\cdot\\frac{3}{2}\\cdot\\frac{1}{2}\\Gamma\\left(\\frac{1}{2}\\right)$。","$\\frac{5\\cdot 3\\cdot 1}{2\\cdot 2\\cdot 2}=\\frac{15}{8}$。","$\\Gamma\\left(\\frac{7}{2}\\right)=\\frac{15\\sqrt{\\pi}}{8}\\approx 3.323$。"],"answer":"$\\frac{15\\sqrt{\\pi}}{8}$"},{"title":"偶數次方乘 Gaussian","prompt":"$\\int_0^{\\infty}x^4e^{-x^2}\\,dx$","problemId":"burst-int-009","steps":["$m=4$，用 $\\int_0^{\\infty}x^me^{-x^2}\\,dx=\\frac{1}{2}\\Gamma\\left(\\frac{m+1}{2}\\right)$：$\\frac{1}{2}\\Gamma\\left(\\frac{5}{2}\\right)$。","$\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3}{2}\\cdot\\frac{1}{2}\\sqrt{\\pi}=\\frac{3\\sqrt{\\pi}}{4}$。","答案 $\\frac{1}{2}\\cdot\\frac{3\\sqrt{\\pi}}{4}=\\frac{3\\sqrt{\\pi}}{8}\\approx 0.6647$。"],"answer":"$\\frac{3\\sqrt{\\pi}}{8}$"},{"title":"負的半整數","prompt":"$\\Gamma\\left(-\\frac{3}{2}\\right)$","steps":["往下推要除：$\\Gamma\\left(-\\frac{1}{2}\\right)=\\frac{\\Gamma(1/2)}{-1/2}=-2\\sqrt{\\pi}$。","$\\Gamma\\left(-\\frac{3}{2}\\right)=\\frac{\\Gamma(-1/2)}{-3/2}=(-2\\sqrt{\\pi})\\cdot\\left(-\\frac{2}{3}\\right)=\\frac{4\\sqrt{\\pi}}{3}\\approx 2.363$。","正負號：$(-1,0)$ 這段是負的，$(-2,-1)$ 這段又變正，跟答案一致。"],"answer":"$\\frac{4\\sqrt{\\pi}}{3}$"}],"pitfalls":["往上乘錯數：$\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3}{2}\\Gamma\\left(\\frac{3}{2}\\right)$，不是 $\\frac{5}{2}\\Gamma\\left(\\frac{3}{2}\\right)$。","往下推時用乘的：$\\Gamma\\left(-\\frac{1}{2}\\right)=\\frac{\\Gamma(1/2)}{-1/2}$，是除以 $-\\frac{1}{2}$，也就是乘 $-2$。","$x^me^{-x^2}$ 換元後漏了 $\\frac{1}{2}$，或把 $\\Gamma\\left(\\frac{m+1}{2}\\right)$ 寫成 $\\Gamma\\left(\\frac{m}{2}\\right)$。","以為所有 Gamma 值都帶 $\\sqrt{\\pi}$；整數點沒有，半整數點才有。"],"voice":"0d7d5b22","sections":[{"title":"從 $\\sqrt{\\pi}$ 往上爬","beats":[{"show":["$\\Gamma\\left(\\frac{1}{2}\\right)=\\sqrt{\\pi}$"],"note":"起點。","say":"起點是上一課的結果：Gamma 二分之一等於根號 pi。","t":[0,5112]},{"show":["$\\Gamma\\left(\\frac{3}{2}\\right)=\\frac{1}{2}\\Gamma\\left(\\frac{1}{2}\\right)=\\frac{\\sqrt{\\pi}}{2}$"],"note":"乘上「前一格的參數」。","say":"每往上一格，就乘上前一格的參數。Gamma 二分之三是二分之一乘根號 pi。","t":[5112,13152]},{"show":["$\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3}{2}\\Gamma\\left(\\frac{3}{2}\\right)=\\frac{3\\sqrt{\\pi}}{4}$"],"say":"再上一格，乘的是二分之三，不是二分之五，得四分之三根號 pi。","t":[13152,19920]}],"check":0},{"title":"一般式","beats":[{"show":["$\\Gamma\\left(\\frac{7}{2}\\right)=\\frac{5}{2}\\cdot\\frac{3}{2}\\cdot\\frac{1}{2}\\Gamma\\left(\\frac{1}{2}\\right)$"],"say":"Gamma 二分之七一路往下拆：乘二分之五、二分之三、二分之一，再乘 Gamma 二分之一。","t":[19920,28320]},{"show":["$\\Gamma\\left(n+\\frac{1}{2}\\right)=\\frac{1\\cdot3\\cdot5\\cdots(2n-1)}{2^{n}}\\sqrt{\\pi}$"],"note":"分子是連續奇數，分母是 $2$ 的次方。","say":"規律是：分子是連續奇數的乘積，分母是二的次方，最後乘根號 pi。","t":[28320,35520]}],"predict":{"ask":"$\\Gamma\\left(\\frac{7}{2}\\right)$ 是？","options":[{"label":"$\\frac{15\\sqrt{\\pi}}{8}$","correct":true},{"label":"$\\frac{15\\sqrt{\\pi}}{4}$","why":"少了一個 $\\frac{1}{2}$：三個因子的分母是 $2\\cdot 2\\cdot 2=8$。"},{"label":"$\\frac{15}{8}$","why":"最後要乘 $\\Gamma\\left(\\frac{1}{2}\\right)=\\sqrt{\\pi}$，半整數點的值帶 $\\sqrt{\\pi}$。"}]}},{"title":"往下推","beats":[{"show":["$\\Gamma(s)=\\frac{\\Gamma(s+1)}{s}$"],"note":"往上是乘，往下是除。","say":"往負的方向推，要把遞迴倒過來：往上是乘，往下是除。","t":[35520,41712]},{"show":["$\\Gamma\\left(-\\frac{1}{2}\\right)=\\frac{\\Gamma(1/2)}{-1/2}=-2\\sqrt{\\pi}$"],"say":"Gamma 負二分之一，是根號 pi 除以負二分之一，也就是乘負二，得負二根號 pi。","t":[41712,49440]},{"show":["$\\Gamma\\left(-\\frac{3}{2}\\right)=\\frac{\\Gamma(-1/2)}{-3/2}=\\frac{4\\sqrt{\\pi}}{3}$"],"note":"正負號每過一個負整數翻一次。","say":"再往下一格，除以負二分之三，負負得正，得三分之四根號 pi。正負號每過一個負整數翻一次。","t":[49440,59328]}],"check":2},{"title":"$x^me^{-x^2}$ 的公式","beats":[{"show":["令 $u=x^2$：$x^m\\,dx=\\frac{1}{2}u^{(m-1)/2}\\,du$"],"note":"$dx=\\frac{du}{2\\sqrt{u}}$","say":"令 u 等於 x 平方，dx 是二根號 u 分之 du，x 的 m 次方 dx 整理成二分之一乘 u 的次方。","t":[59328,67704]},{"show":["$\\int_0^{\\infty}x^me^{-x^2}\\,dx=\\frac{1}{2}\\Gamma\\left(\\frac{m+1}{2}\\right)$"],"note":"$m>-1$。","say":"所以 x 的 m 次方乘 e 的負 x 平方次方，一條公式全部管：二分之一乘 Gamma 二分之 m 加一。","t":[67704,76032]},{"show":["$m$ 奇數：整數點，沒有 $\\pi$"],"note":"例：$m=3$ 得 $\\frac{1}{2}\\Gamma(2)=\\frac{1}{2}$。","say":"m 是奇數，二分之 m 加一是整數，答案是階乘的一半，沒有 pi。","t":[76032,82512]}],"check":3},{"title":"偶數次方帶 $\\sqrt{\\pi}$","beats":[{"show":["$m$ 偶數：半整數點，帶 $\\sqrt{\\pi}$"],"say":"m 是偶數，二分之 m 加一是半整數，答案一定帶根號 pi。","t":[82512,88320]},{"show":["$\\int_0^{\\infty}x^4e^{-x^2}\\,dx=\\frac{1}{2}\\Gamma\\left(\\frac{5}{2}\\right)$"],"note":"$=\\frac{1}{2}\\cdot\\frac{3\\sqrt{\\pi}}{4}=\\frac{3\\sqrt{\\pi}}{8}$","say":"例如 m 等於四，是二分之一乘 Gamma 二分之五，得八分之三根號 pi。","t":[88320,94920]},{"show":["$x^3e^{-x^2}$ 換元積得出來","$x^4e^{-x^2}$ 總剩一個 Gaussian"],"say":"這解釋了一件事：三次方用換元直接積得出來，四次方怎麼分部積分都會剩下一個鐘形積分。","t":[94920,103800]}],"check":1}],"checks":[{"ask":"$\\Gamma\\left(\\frac{5}{2}\\right)$ 是？","options":[{"label":"$\\frac{3\\sqrt{\\pi}}{4}$","correct":true},{"label":"$\\frac{3\\sqrt{\\pi}}{2}$","why":"$\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3}{2}\\Gamma\\left(\\frac{3}{2}\\right)$，而 $\\Gamma\\left(\\frac{3}{2}\\right)=\\frac{\\sqrt{\\pi}}{2}$，不是 $\\sqrt{\\pi}$。"},{"label":"$\\frac{15\\sqrt{\\pi}}{4}$","why":"多乘了 $\\frac{5}{2}$：遞迴乘的是 $s$，$\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3}{2}\\Gamma\\left(\\frac{3}{2}\\right)$。"}]},{"ask":"$\\int_0^{\\infty}x^2e^{-x^2}\\,dx$ 是？","options":[{"label":"$\\frac{\\sqrt{\\pi}}{4}$","correct":true},{"label":"$\\frac{\\sqrt{\\pi}}{2}$","why":"公式是 $\\frac{1}{2}\\Gamma\\left(\\frac{3}{2}\\right)=\\frac{1}{2}\\cdot\\frac{\\sqrt{\\pi}}{2}$，漏了前面的 $\\frac{1}{2}$。"},{"label":"$\\frac{1}{2}$","why":"那是 $m=3$ 的答案 $\\frac{1}{2}\\Gamma(2)$。$m=2$ 對應 $\\Gamma\\left(\\frac{3}{2}\\right)$，會帶 $\\sqrt{\\pi}$。"}]},{"ask":"$\\Gamma\\left(-\\frac{1}{2}\\right)$ 是？","options":[{"label":"$-2\\sqrt{\\pi}$","correct":true},{"label":"$2\\sqrt{\\pi}$","why":"$\\Gamma\\left(-\\frac{1}{2}\\right)=\\frac{\\Gamma(1/2)}{-1/2}$，除以負數，結果是負的。"},{"label":"$-\\frac{\\sqrt{\\pi}}{2}$","why":"往下推要除以 $-\\frac{1}{2}$，不是乘以 $-\\frac{1}{2}$。"}]},{"ask":"$\\int_0^{\\infty}x^3e^{-x^2}\\,dx$ 是？","options":[{"label":"$\\frac{1}{2}$","correct":true},{"label":"$\\frac{\\sqrt{\\pi}}{4}$","why":"$m=3$ 對應 $\\Gamma\\left(\\frac{3+1}{2}\\right)=\\Gamma(2)=1$，是整數點，沒有 $\\sqrt{\\pi}$。"},{"label":"$1$","why":"公式前面有 $\\frac{1}{2}$：$\\frac{1}{2}\\Gamma(2)=\\frac{1}{2}$。"}]}],"practice":[{"id":"mob-gamma-003","core":true},{"id":"mob-gamma-004","core":true},{"id":"mob-gamma-009","core":true},{"id":"rel-boss-004","core":true},{"id":"burst-int-009","core":true},{"id":"burst-int-010","core":true},{"id":"depth-int-026"},{"id":"mob-gamma-007"},{"id":"td-int-006","challenge":true,"note":"挑戰：整條實數線、指數有係數 3，先用偶函數變成兩倍，再縮放。"}]},"gamma-scaled":{"id":"gamma-scaled","prerequisites":["gamma-half-integer","u-sub-definite"],"next":["beta-function"],"related":["feynman-trick-basic","gamma-definition"],"objectives":["推出並使用 $\\int_0^{\\infty}x^{s-1}e^{-ax}\\,dx=\\frac{\\Gamma(s)}{a^s}$（$a>0$）。","推出並使用 $\\int_0^{\\infty}x^{s-1}e^{-ax^p}\\,dx=\\frac{\\Gamma(s/p)}{p\\,a^{s/p}}$，處理 $e^{-x^3}$、$e^{-2x^2}$ 這類指數。","用「量綱」檢查答案：$x$ 的尺度是 $\\frac{1}{a}$，結果一定帶 $a$ 的 $-s$ 次方。"],"concept":[{"heading":"① 指數裡有係數：令 $u=ax$","body":["$\\int_0^{\\infty}x^{s-1}e^{-ax}\\,dx$（$a>0$）：令 $u=ax$，$x=\\frac{u}{a}$，$dx=\\frac{du}{a}$。$x^{s-1}\\,dx=\\left(\\frac{u}{a}\\right)^{s-1}\\frac{du}{a}=\\frac{u^{s-1}\\,du}{a^s}$。","所以結果是 $\\frac{\\Gamma(s)}{a^s}$。〈Gamma 函數：定義與遞迴〉裡的 $\\frac{\\Gamma(k+1)}{a^{k+1}}$ 是 $s=k+1$ 的特例。$a\\le 0$ 時 $e^{-ax}$ 不衰減，積分發散。"],"tex":["\\int_0^{\\infty}x^{s-1}e^{-ax}\\,dx=\\frac{\\Gamma(s)}{a^{s}}\\qquad(s>0,\\ a>0)"]},{"heading":"② 指數裡是 $x^p$：令 $u=ax^p$","body":["$\\int_0^{\\infty}x^{s-1}e^{-ax^p}\\,dx$（$p>0$）：令 $u=ax^p$，$x=\\left(\\frac{u}{a}\\right)^{1/p}$，$dx=\\frac{1}{p}a^{-1/p}u^{1/p-1}\\,du$。","合併 $u$ 的次方：$x^{s-1}\\,dx=\\frac{1}{p}a^{-s/p}u^{s/p-1}\\,du$。結果是 $\\frac{\\Gamma(s/p)}{p\\,a^{s/p}}$。","$p=1$ 回到 ①；$p=2$ 就是上一課的 $\\int_0^{\\infty}x^me^{-x^2}\\,dx=\\frac{1}{2}\\Gamma\\left(\\frac{m+1}{2}\\right)$（$s=m+1$、$a=1$）。"],"tex":["\\int_0^{\\infty}x^{s-1}e^{-a x^{p}}\\,dx=\\frac{\\Gamma(s/p)}{p\\,a^{s/p}}"]},{"heading":"③ 量綱檢查","body":["如果 $x$ 帶單位（例如秒），$a$ 的單位就是 1/秒，指數 $ax$ 才是純數。積分 $\\int x^{s-1}\\,dx$ 的單位是 秒ˢ，所以答案一定長成「純數 $\\times\\,a^{-s}$」。寫出 $a^{-(s-1)}$ 或 $a^{-s-1}$，量綱就對不上，一定是 $dx$ 換錯了。$p$ 的情況同理：$ax^p$ 是純數，$x$ 的尺度是 $a^{-1/p}$，答案帶 $a^{-s/p}$。"]}],"workedExamples":[{"title":"半整數加係數","prompt":"$\\int_0^{\\infty}x^{3/2}e^{-4x}\\,dx$","problemId":"rel-hard-int-002","steps":["$x^{3/2}=x^{s-1}$，$s=\\frac{5}{2}$；$a=4$。","結果 $\\frac{\\Gamma(5/2)}{4^{5/2}}$。$\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3\\sqrt{\\pi}}{4}$，$4^{5/2}=(\\sqrt{4})^5=32$。","答案 $\\frac{3\\sqrt{\\pi}/4}{32}=\\frac{3\\sqrt{\\pi}}{128}\\approx 0.0415$。"],"answer":"$\\frac{3\\sqrt{\\pi}}{128}$"},{"title":"指數是 $x^3$","prompt":"$\\int_0^{\\infty}e^{-x^3}\\,dx$","steps":["$s-1=0$，$s=1$；$p=3$；$a=1$。","結果 $\\frac{\\Gamma(1/3)}{3}$。","用遞迴改寫：$\\Gamma\\left(\\frac{4}{3}\\right)=\\frac{1}{3}\\Gamma\\left(\\frac{1}{3}\\right)$，所以答案也是 $\\Gamma\\left(\\frac{4}{3}\\right)\\approx 0.8930$。這個值沒有更簡單的閉式。"],"answer":"$\\frac{\\Gamma(1/3)}{3}=\\Gamma\\left(\\frac{4}{3}\\right)$"},{"title":"$x^2$ 指數又有係數","prompt":"$\\int_0^{\\infty}x^4e^{-2x^2}\\,dx$","problemId":"hc-spec-006","steps":["$x^4=x^{s-1}$，$s=5$；$p=2$；$a=2$。","結果 $\\frac{\\Gamma(5/2)}{2\\cdot 2^{5/2}}$。","$\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3\\sqrt{\\pi}}{4}$；$2^{5/2}=4\\sqrt{2}$，所以分母 $2\\cdot 4\\sqrt{2}=8\\sqrt{2}$。","答案 $\\frac{3\\sqrt{\\pi}/4}{8\\sqrt{2}}=\\frac{3\\sqrt{\\pi}}{32\\sqrt{2}}\\approx 0.1175$。"],"answer":"$\\frac{3\\sqrt{\\pi}}{32\\sqrt{2}}$"}],"pitfalls":["$a^s$ 寫成 $a^{s-1}$：漏了 $dx=\\frac{du}{a}$ 的那一個 $\\frac{1}{a}$。","指數是 $x^p$ 時忘了前面的 $\\frac{1}{p}$。","把 $s$ 讀錯：$x^{3/2}$ 對應 $s=\\frac{5}{2}$，不是 $\\frac{3}{2}$。","$a\\le 0$ 也套公式；積分只在 $a>0$ 收斂。"],"voice":"ccb1bfdf","sections":[{"title":"令 $u=ax$","beats":[{"show":["$\\int_0^{\\infty}x^{s-1}e^{-ax}\\,dx$"],"note":"指數裡有係數 $a>0$。","say":"指數裡多了一個係數 a，令 u 等於 a x，把它變回標準的 Gamma。","t":[0,6000]},{"show":["$x=\\frac{u}{a}$，$dx=\\frac{du}{a}$"],"say":"x 是 a 分之 u，dx 是 a 分之 du，兩個地方都會吐出 a。","t":[6000,11688]},{"show":["$x^{s-1}\\,dx=\\frac{u^{s-1}\\,du}{a^s}$"],"note":"$a^{-(s-1)}$ 再乘 $a^{-1}$。","say":"x 的 s 減一次方給出 a 的負 s 加一次方，dx 再給一個 a 分之一，合起來是 a 的 s 次方分之一。","t":[11688,20184]},{"show":["$=\\frac{\\Gamma(s)}{a^s}$"],"note":"$s>0$，$a>0$。","say":"所以答案是 Gamma s 除以 a 的 s 次方。","t":[20184,24024]}],"check":2},{"title":"讀出 $s$ 和 $a$","beats":[{"show":["$\\int_0^{\\infty}x^{3/2}e^{-4x}\\,dx$"],"note":"$x^{3/2}=x^{s-1}$，所以 $s=\\frac{5}{2}$；$a=4$。","say":"先讀參數：x 的二分之三次方是 x 的 s 減一次方，所以 s 是二分之五，不是二分之三；a 是四。","t":[24024,33504]},{"show":["$\\frac{\\Gamma(5/2)}{4^{5/2}}$"],"note":"$\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3\\sqrt{\\pi}}{4}$，$4^{5/2}=32$。","say":"Gamma 二分之五是四分之三根號 pi，四的二分之五次方是根號四的五次方，三十二。","t":[33504,41640]},{"show":["$=\\frac{3\\sqrt{\\pi}}{128}\\approx 0.0415$"],"say":"相除得一百二十八分之三根號 pi。","t":[41640,45432]}],"check":0},{"title":"量綱檢查","beats":[{"show":["$x$ 是秒，$a$ 就是 1/秒"],"note":"指數 $ax$ 必須是純數。","say":"假設 x 的單位是秒，指數 a x 必須是純數，所以 a 的單位是每秒。","t":[45432,51912]},{"show":["答案 = 純數 $\\times\\,a^{-s}$"],"note":"$\\int x^{s-1}\\,dx$ 的單位是 秒ˢ。","say":"積分的單位是秒的 s 次方，所以答案一定長成純數乘 a 的負 s 次方。","t":[51912,58368]},{"show":["寫出 $a^{-(s-1)}$：$dx$ 換錯了"],"say":"寫出 a 的負 s 加一次方，量綱就對不上，一定是 dx 那一個 a 分之一漏了。","t":[58368,65232]},{"show":["$a\\le 0$：積分發散"],"note":"$e^{-ax}$ 不衰減。","say":"還有，a 小於等於零時，e 的負 a x 次方不會衰減，積分發散，公式不能用。","t":[65232,73128]}],"check":3},{"title":"指數是 $x^p$","beats":[{"show":["$\\int_0^{\\infty}x^{s-1}e^{-ax^p}\\,dx$"],"note":"令 $u=ax^p$，$p>0$。","say":"指數裡是 x 的 p 次方，就令 u 等於 a 乘 x 的 p 次方。","t":[73128,78384]},{"show":["$=\\frac{\\Gamma(s/p)}{p\\,a^{s/p}}$"],"note":"$p=1$ 回到上面；$p=2$ 是上一課的公式。","say":"合併 u 的次方之後，答案是 Gamma p 分之 s，除以 p，再除以 a 的 p 分之 s 次方。","t":[78384,86016]},{"show":["$\\int_0^{\\infty}e^{-x^3}\\,dx=\\frac{\\Gamma(1/3)}{3}$"],"note":"$=\\Gamma\\left(\\frac{4}{3}\\right)\\approx 0.8930$","say":"例如 e 的負 x 三次方：s 是一，p 是三，得三分之一乘 Gamma 三分之一，用遞迴就是 Gamma 三分之四。","t":[86016,95448]}],"check":1},{"title":"$x^2$ 加係數","beats":[{"show":["$\\int_0^{\\infty}x^4e^{-2x^2}\\,dx$"],"note":"$p=2$，$a=2$。","say":"最後一題：x 四次方乘 e 的負二 x 平方次方，p 是二，a 是二。","t":[95448,102192]},{"show":["$\\frac{\\Gamma(5/2)}{2\\cdot 2^{5/2}}=\\frac{3\\sqrt{\\pi}}{32\\sqrt{2}}$"],"note":"$2^{5/2}=4\\sqrt{2}$","say":"代進公式：Gamma 二分之五除以二，再除以二的二分之五次方，約零點一一七五。","t":[102192,110016]}],"predict":{"ask":"這一題的 $s$ 是多少？","options":[{"label":"$5$","correct":true},{"label":"$4$","why":"$x^4$ 是 $x^{s-1}$，所以 $s-1=4$，$s=5$。"},{"label":"$\\frac{5}{2}$","why":"$\\frac{5}{2}$ 是 $\\frac{s}{p}$，是 $\\Gamma$ 裡面的參數；$s$ 本身是 $5$。"}]}}],"checks":[{"ask":"$\\int_0^{\\infty}x^2e^{-5x}\\,dx$ 是？","options":[{"label":"$\\frac{2}{125}$","correct":true},{"label":"$\\frac{2}{25}$","why":"分母是 $a^s$，$s=3$，要 $5^3=125$；寫成 $5^2$ 是漏了 $dx=\\frac{du}{5}$。"},{"label":"$250$","why":"$a$ 在分母：指數衰減得越快，面積越小。"}]},{"ask":"$\\int_0^{\\infty}e^{-x^4}\\,dx$ 是？","options":[{"label":"$\\Gamma\\left(\\frac{5}{4}\\right)$","correct":true},{"label":"$\\Gamma\\left(\\frac{1}{4}\\right)$","why":"公式是 $\\frac{\\Gamma(1/4)}{4}$，漏了 $\\frac{1}{p}$；$\\frac{\\Gamma(1/4)}{4}=\\Gamma\\left(\\frac{5}{4}\\right)$。"},{"label":"$\\Gamma(4)$","why":"$p=4$ 出現在 $\\Gamma$ 的分母位置：$\\Gamma\\left(\\frac{s}{p}\\right)=\\Gamma\\left(\\frac{1}{4}\\right)$，不是 $\\Gamma(4)$。"}]},{"ask":"$\\int_0^{\\infty}x^{s-1}e^{-ax}\\,dx=\\frac{\\Gamma(s)}{a^s}$ 裡的 $a^s$ 是從哪裡來的？","options":[{"label":"$x^{s-1}$ 貢獻 $a^{-(s-1)}$，$dx$ 再貢獻 $a^{-1}$","correct":true},{"label":"$e^{-ax}$ 換元後變成 $a^se^{-u}$","why":"$e^{-ax}$ 換元後就是 $e^{-u}$，不帶 $a$；$a$ 全部來自 $x^{s-1}$ 與 $dx$。"},{"label":"$\\Gamma$ 函數本身的性質 $\\Gamma(as)=a^s\\Gamma(s)$","why":"沒有這個性質；Gamma 不是這樣縮放的。"}]},{"ask":"$\\int_0^{\\infty}xe^{-ax}\\,dx$ 對哪些 $a$ 收斂？","options":[{"label":"$a>0$","correct":true},{"label":"$a\\ne 0$","why":"$a<0$ 時 $e^{-ax}$ 是增長的指數，積分發散。"},{"label":"所有實數 $a$","why":"$a=0$ 時是 $\\int_0^{\\infty}x\\,dx$，發散。"}]}],"practice":[{"id":"rel-adv-011","core":true},{"id":"burst-int-001","core":true},{"id":"rel-hard-int-001","core":true},{"id":"rel-hard-int-002","core":true},{"id":"hc-spec-006","core":true},{"id":"burst-boss-param-002"},{"id":"td-int-006","challenge":true,"note":"挑戰：整條實數線，偶函數先乘 $2$，再套 $p=2$、$a=3$。"}]},"beta-function":{"id":"beta-function","prerequisites":["gamma-scaled","improper-p-test","integration-by-parts","u-sub-definite"],"next":["beta-gamma-relation"],"related":[],"objectives":["寫得出 $\\mathrm{B}(p,q)=\\int_0^1x^{p-1}(1-x)^{q-1}\\,dx$，說得出它在 $p>0$、$q>0$ 時收斂，並且 $\\mathrm{B}(p,q)=\\mathrm{B}(q,p)$。","從題目的次方正確讀出 $p$、$q$（次方加 1）。","用分部積分的遞迴算出整數點的值 $\\mathrm{B}(m,n)=\\frac{(m-1)!\\,(n-1)!}{(m+n-1)!}$，並認得 $[0,a]$ 與 $[0,\\infty)$ 上的變形。"],"concept":[{"heading":"① 另一整族積分：$[0,1]$ 上的 $x^a(1-x)^b$","body":["$\\int_0^1x^2(1-x)^3\\,dx$、$\\int_0^1\\sqrt{x}\\,(1-x)\\,dx$、$\\int_0^1\\frac{dx}{\\sqrt{x(1-x)}}$……展開或換元都能做，但每題都不同。Gamma 統一了 $[0,\\infty)$ 上的 $x^ke^{-x}$，Beta 統一 $[0,1]$ 上的 $x^a(1-x)^b$：","讀題方法跟 Gamma 一樣是「次方加 1」：$x^2$ 對應 $p=3$，$(1-x)^3$ 對應 $q=4$，所以 $\\int_0^1x^2(1-x)^3\\,dx=\\mathrm{B}(3,4)$。"],"tex":["B(p,q)=\\int_0^{1}x^{p-1}(1-x)^{q-1}\\,dx"]},{"heading":"② 收斂與對稱","body":["兩個端點都可能是瑕點。$x\\to 0^+$ 時被積函數像 $x^{p-1}$，由 $p$ 判別要 $p-1>-1$，即 $p>0$；$x\\to 1^-$ 時像 $(1-x)^{q-1}$，要 $q>0$。所以：此積分表示式在 $p>0$ 且 $q>0$ 時收斂。","令 $x=1-t$，兩個因子對調、區間不變：$\\mathrm{B}(p,q)=\\mathrm{B}(q,p)$。"]},{"heading":"③ 整數點：用分部積分降次","body":["對 $\\mathrm{B}(p,q+1)=\\int_0^1x^{p-1}(1-x)^q\\,dx$ 取 $u=(1-x)^q$、$dv=x^{p-1}\\,dx$。邊界項 $\\left[\\frac{x^p(1-x)^q}{p}\\right]_0^1=0$，得 $\\mathrm{B}(p,q+1)=\\frac{q}{p}\\mathrm{B}(p+1,q)$：把 $(1-x)$ 的次數搬一個給 $x$。","一直搬到 $(1-x)$ 的次數變 $0$，再用 $\\mathrm{B}(p,1)=\\int_0^1x^{p-1}\\,dx=\\frac{1}{p}$，就得到整數點的公式（下一課會用 Gamma 給出所有 $p$、$q$ 的版本）。"],"tex":["B(m,n)=\\frac{(m-1)!\\,(n-1)!}{(m+n-1)!}\\qquad(m,n\\ \\text{為正整數})"]},{"heading":"④ 兩種常見的變形","body":["區間 $[0,a]$：令 $x=at$，$\\int_0^ax^{p-1}(a-x)^{q-1}\\,dx=a^{p+q-1}\\mathrm{B}(p,q)$。","區間 $[0,\\infty)$：令 $x=\\frac{t}{1+t}$，$1-x=\\frac{1}{1+t}$，$dx=\\frac{dt}{(1+t)^2}$，得 $\\mathrm{B}(p,q)=\\int_0^{\\infty}\\frac{t^{p-1}}{(1+t)^{p+q}}\\,dt$。看到 $[0,\\infty)$ 上「冪次除以 $(1+t)$ 的冪次」也要想到 Beta。"]}],"workedExamples":[{"title":"整數次方","prompt":"$\\int_0^1x^3(1-x)^4\\,dx$","problemId":"burst-int-007","steps":["次方加 1：$p=4$，$q=5$，積分是 $\\mathrm{B}(4,5)$。","$\\mathrm{B}(4,5)=\\frac{3!\\,4!}{8!}=\\frac{6\\cdot 24}{40320}=\\frac{144}{40320}$。","約分：$\\frac{1}{280}$。展開 $(1-x)^4$ 再逐項積分也會得到 $\\frac{1}{280}$，但要五項。"],"answer":"$\\frac{1}{280}$"},{"title":"區間是 $[0,2]$","prompt":"$\\int_0^2x^2(2-x)^3\\,dx$","steps":["令 $x=2t$，$dx=2\\,dt$：$x^2=4t^2$，$(2-x)^3=8(1-t)^3$。","積分 $=\\int_0^1 4t^2\\cdot 8(1-t)^3\\cdot 2\\,dt=64\\,\\mathrm{B}(3,4)$。也就是公式 $a^{p+q-1}=2^{3+4-1}=2^6$。","$\\mathrm{B}(3,4)=\\frac{2!\\,3!}{6!}=\\frac{12}{720}=\\frac{1}{60}$，答案 $\\frac{64}{60}=\\frac{16}{15}$。"],"answer":"$\\frac{16}{15}$"},{"title":"無窮區間上的 Beta","prompt":"$\\int_0^{\\infty}\\frac{t}{(1+t)^5}\\,dt$","steps":["對照 $\\frac{t^{p-1}}{(1+t)^{p+q}}$：$p-1=1$，$p=2$；$p+q=5$，$q=3$。","積分 $=\\mathrm{B}(2,3)=\\frac{1!\\,2!}{4!}=\\frac{2}{24}=\\frac{1}{12}$。","檢查收斂：$t\\to\\infty$ 時被積函數 $\\sim\\frac{1}{t^4}$，收斂；跟 $\\mathrm{B}$ 的條件 $p$、$q>0$ 一致。"],"answer":"$\\frac{1}{12}$"}],"pitfalls":["次方直接當 $p$、$q$：$x^2(1-x)^3$ 是 $\\mathrm{B}(3,4)$，不是 $\\mathrm{B}(2,3)$。","整數公式分母寫成 $(m+n)!$，正確是 $(m+n-1)!$。","區間 $[0,a]$ 忘了乘 $a^{p+q-1}$。","以為 $p$ 或 $q$ 小於 $1$ 時積分發散；只要大於 $0$ 都收斂。"],"voice":"382e0898","sections":[{"title":"另一整族積分","beats":[{"show":["$\\int_0^1x^2(1-x)^3\\,dx$","$\\int_0^1\\sqrt{x}\\,(1-x)\\,dx$、…"],"note":"展開或換元都能做，但每題都不同。","say":"零到一上，x 的幾次方乘一減 x 的幾次方，這種積分每題做法都不同。","t":[0,6960]},{"show":["$\\mathrm{B}(p,q)=\\int_0^{1}x^{p-1}(1-x)^{q-1}\\,dx$"],"note":"Gamma 管 $[0,\\infty)$，Beta 管 $[0,1]$。","say":"Gamma 統一了零到無限大的那一族，Beta 函數統一零到一的這一族。","t":[6960,13032]},{"show":["讀題：次方加 1"],"note":"$x^2$ 對應 $p=3$，$(1-x)^3$ 對應 $q=4$。","say":"讀題的方法跟 Gamma 一樣，次方加一：x 平方對應 p 等於三，一減 x 的三次方對應 q 等於四。","t":[13032,21528]}],"check":0},{"title":"什麼時候收斂","beats":[{"show":["$x\\to 0^+$：像 $x^{p-1}$，要 $p>0$"],"say":"兩個端點都可能是瑕點。靠近零，被積函數像 x 的 p 減一次方，p 判別要 p 大於零。","t":[21528,30384]},{"show":["$x\\to 1^-$：像 $(1-x)^{q-1}$，要 $q>0$"],"say":"靠近一，像一減 x 的 q 減一次方，要 q 大於零。兩端分開檢查。","t":[30384,37752]},{"show":["$p>0$ 且 $q>0$ 時收斂"],"note":"小於 $1$ 也可以，只要大於 $0$。","say":"所以 p、q 都大於零就收斂。p 小於一只是端點衝到無限大，面積仍然有限。","t":[37752,46272]}],"check":1},{"title":"對稱","beats":[{"show":["令 $x=1-t$"],"note":"兩個因子對調，區間不變。","say":"令 x 等於一減 t，x 和一減 x 互換位置，零到一這段區間還是零到一。","t":[46272,53568]},{"show":["$\\mathrm{B}(p,q)=\\mathrm{B}(q,p)$"],"say":"所以 Beta 函數的兩個參數可以對調，是同一個積分換了變數的名字。","t":[53568,59928]}],"check":3},{"title":"整數點","beats":[{"show":["$\\mathrm{B}(p,q+1)=\\frac{q}{p}\\mathrm{B}(p+1,q)$"],"note":"分部積分：$u=(1-x)^q$，邊界項是 $0$。","say":"分部積分一次，把一減 x 的次數搬一個給 x，前面多出 p 分之 q。","t":[59928,66648]},{"show":["$\\mathrm{B}(p,1)=\\int_0^1x^{p-1}\\,dx=\\frac{1}{p}$"],"say":"一直搬到一減 x 的次數變零，剩下 x 的 p 減一次方，積分是 p 分之一。","t":[66648,73608]},{"show":["$\\mathrm{B}(m,n)=\\frac{(m-1)!\\,(n-1)!}{(m+n-1)!}$"],"note":"$m$、$n$ 為正整數。","say":"整理起來，整數點的公式是兩個階乘相乘，除以 m 加 n 減一的階乘。","t":[73608,80472]}],"check":2},{"title":"算一個","beats":[{"show":["$\\int_0^1x^3(1-x)^4\\,dx=\\mathrm{B}(4,5)$"],"note":"次方加 1：$p=4$，$q=5$。","say":"x 三次方乘一減 x 的四次方，次方各加一，是 Beta 四、五。","t":[80472,86760]},{"show":["分子 $3!\\,4!=6\\cdot 24=144$"],"say":"分子是三階乘乘四階乘，六乘二十四，一百四十四。","t":[86760,92592]}],"predict":{"ask":"分母是？","options":[{"label":"$8!$，答案 $\\frac{1}{280}$","correct":true},{"label":"$(4+5)!$","why":"分母是 $(m+n-1)!$，$4+5-1=8$。"},{"label":"$4!\\,5!$","why":"階乘的乘積在分子，而且是 $(m-1)!\\,(n-1)!$；分母是 $(m+n-1)!$。"}]}},{"title":"兩種變形","beats":[{"show":["$\\int_0^ax^{p-1}(a-x)^{q-1}\\,dx$","$=a^{p+q-1}\\mathrm{B}(p,q)$"],"note":"令 $x=at$。","say":"區間是零到 a，令 x 等於 a t，多出 a 的 p 加 q 減一次方。","t":[92592,98592]},{"show":["$\\int_0^2x^2(2-x)^3\\,dx=2^6\\,\\mathrm{B}(3,4)$","$=\\frac{16}{15}$"],"say":"例如零到二：二的六次方乘 Beta 三、四，六十四乘六十分之一，得十五分之十六。","t":[98592,106728]},{"show":["$\\mathrm{B}(p,q)=\\int_0^{\\infty}\\frac{t^{p-1}}{(1+t)^{p+q}}\\,dt$"],"note":"令 $x=\\frac{t}{1+t}$。","say":"令 x 等於一加 t 分之 t，Beta 也能寫成零到無限大的積分，分母是一加 t 的 p 加 q 次方。","t":[106728,114888]}],"predict":{"ask":"$\\int_0^{\\infty}\\frac{t}{(1+t)^5}\\,dt$ 是哪個 Beta？","options":[{"label":"$\\mathrm{B}(2,3)=\\frac{1}{12}$","correct":true},{"label":"$\\mathrm{B}(1,5)$","why":"$t$ 的次方是 $p-1$，所以 $p=2$；$5$ 是 $p+q$，不是 $q$。"},{"label":"$\\mathrm{B}(2,5)$","why":"分母的次方是 $p+q=5$，所以 $q=5-2=3$。"}]}}],"checks":[{"ask":"$\\int_0^1x^2(1-x)^3\\,dx$ 用 Beta 寫是？","options":[{"label":"$\\mathrm{B}(3,4)$","correct":true},{"label":"$\\mathrm{B}(2,3)$","why":"$\\mathrm{B}(p,q)$ 的次方是 $p-1$ 與 $q-1$，所以要各加 1。"},{"label":"$\\frac{\\mathrm{B}(2,3)}{2}$","why":"不需要額外的係數；只要把次方加 1。"}]},{"ask":"$\\int_0^1x^{p-1}(1-x)^{q-1}\\,dx$ 在什麼條件下收斂？","options":[{"label":"$p>0$ 而且 $q>0$","correct":true},{"label":"$p>1$ 而且 $q>1$","why":"太嚴了：$p=\\frac{1}{2}$ 時 $x\\to 0$ 附近像 $x^{-1/2}$，$p$ 判別說收斂。"},{"label":"$p+q>0$","why":"兩端要分開檢查：$p=-\\frac{1}{2}$、$q=2$ 時 $p+q>0$，但 $0$ 那端像 $x^{-3/2}$，發散。"}]},{"ask":"$\\mathrm{B}(1,q)$ 是？","options":[{"label":"$\\frac{1}{q}$","correct":true},{"label":"$q$","why":"$\\int_0^1(1-x)^{q-1}\\,dx=\\frac{1}{q}$，積分會除以 $q$。"},{"label":"$1$","why":"只有 $q=1$ 時才是 $1$；一般是 $\\frac{1}{q}$。"}]},{"ask":"$\\mathrm{B}(2,5)$ 與 $\\mathrm{B}(5,2)$ 的關係？","options":[{"label":"相等","correct":true},{"label":"$\\mathrm{B}(2,5)$ 比較大，因為 $5$ 比較大的那邊在後面","why":"令 $x=1-t$，兩個因子互換、區間不變，所以兩者相等。"},{"label":"互為倒數","why":"沒有這個關係；它們是同一個積分換了變數的名字。"}]}],"practice":[{"id":"mob-beta-001","core":true},{"id":"mob-beta-002","core":true},{"id":"mob-beta-003","core":true},{"id":"mob-beta-004","core":true},{"id":"burst-int-007","core":true},{"id":"mob-beta-009"},{"id":"mob-beta-010"},{"id":"burst-rec-003"},{"id":"mob-tech-015"}]},"beta-gamma-relation":{"id":"beta-gamma-relation","prerequisites":["beta-function","gamma-half-integer","change-of-variables","jacobian-determinant"],"next":["beta-trig"],"related":["gamma-half","residue-real-integrals"],"objectives":["寫得出 $\\mathrm{B}(p,q)=\\frac{\\Gamma(p)\\Gamma(q)}{\\Gamma(p+q)}$，並用它算非整數的 Beta 值。","說得出證明的骨架：$\\Gamma(p)\\Gamma(q)$ 寫成二重積分，換成「總和 $u=x+y$、比例 $v=\\frac{x}{x+y}$」兩個變數。","把 $[0,1]$ 與 $[0,\\infty)$ 上的 Beta 型積分化成 Gamma 值計算。"],"concept":[{"heading":"① 公式","body":["Beta 可以完全用 Gamma 表示。整數時它就是上一課的 $\\frac{(m-1)!(n-1)!}{(m+n-1)!}$，因為 $\\Gamma(m)=(m-1)!$。","這條公式讓所有非整數的 Beta 都能算：$\\mathrm{B}\\left(\\frac{1}{2},\\frac{1}{2}\\right)=\\frac{\\Gamma(1/2)^2}{\\Gamma(1)}=\\pi$，$\\mathrm{B}\\left(\\frac{3}{2},\\frac{3}{2}\\right)=\\frac{(\\sqrt{\\pi}/2)^2}{\\Gamma(3)}=\\frac{\\pi/4}{2}=\\frac{\\pi}{8}$。","分母 $\\Gamma(p+q)$ 最容易漏掉：$\\mathrm{B}$ 是三個 Gamma 的組合，不是兩個相乘。"],"tex":["B(p,q)=\\frac{\\Gamma(p)\\,\\Gamma(q)}{\\Gamma(p+q)}"]},{"heading":"② 為什麼：把兩個 Gamma 合成一個二重積分","body":["$\\Gamma(p)\\Gamma(q)=\\int_0^{\\infty}\\int_0^{\\infty}x^{p-1}y^{q-1}e^{-(x+y)}\\,dx\\,dy$。指數只跟 $x+y$ 有關，所以換成兩個新變數：$u=x+y$（總和）、$v=\\frac{x}{x+y}$（$x$ 佔的比例）。反過來 $x=uv$、$y=u(1-v)$，$u$ 從 $0$ 到 $\\infty$、$v$ 從 $0$ 到 $1$，剛好蓋滿第一象限。","代進去：$x^{p-1}y^{q-1}=u^{p+q-2}v^{p-1}(1-v)^{q-1}$，再乘上 Jacobian $u$，被積函數拆成「只有 $u$」乘「只有 $v$」，兩個積分分開算：$u$ 那邊是 $\\Gamma(p+q)$，$v$ 那邊是 $\\mathrm{B}(p,q)$。"]},{"heading":"Jacobian 的計算與嚴格性","body":["$x=uv$、$y=u-uv$：$\\frac{\\partial(x,y)}{\\partial(u,v)}$ 的行列式 $=(v)(-u)-(u)(1-v)=-u$，絕對值是 $u$（〈Jacobian 行列式〉）。","被積函數非負，所以 Fubini–Tonelli 定理保證可以把瑕二重積分寫成累次積分、也可以換變數，不用擔心收斂順序。"],"collapsible":true},{"heading":"③ 一個副產品：再證一次 $\\Gamma\\left(\\frac{1}{2}\\right)=\\sqrt{\\pi}$","body":["$\\mathrm{B}\\left(\\frac{1}{2},\\frac{1}{2}\\right)=\\int_0^1\\frac{dx}{\\sqrt{x(1-x)}}$。令 $x=\\sin^2\\theta$，$dx=2\\sin\\theta\\cos\\theta\\,d\\theta$，$\\sqrt{x(1-x)}=\\sin\\theta\\cos\\theta$，積分變成 $\\int_0^{\\pi/2}2\\,d\\theta=\\pi$。","另一方面 $\\mathrm{B}\\left(\\frac{1}{2},\\frac{1}{2}\\right)=\\frac{\\Gamma(1/2)^2}{\\Gamma(1)}=\\Gamma\\left(\\frac{1}{2}\\right)^2$。所以 $\\Gamma\\left(\\frac{1}{2}\\right)^2=\\pi$，跟〈Γ(1/2) = √π〉的極座標算法得到同一個答案。"]},{"heading":"預告：反射公式","body":["$p+q=1$ 時分母是 $\\Gamma(1)=1$，$\\mathrm{B}(s,1-s)=\\Gamma(s)\\Gamma(1-s)$。可以證明 $\\Gamma(s)\\Gamma(1-s)=\\frac{\\pi}{\\sin(\\pi s)}$（$0<s<1$），證明要用複變（〈用留數算實積分〉）。有了它，$\\int_0^{\\infty}\\frac{dx}{1+x^4}=\\frac{1}{4}\\mathrm{B}\\left(\\frac{1}{4},\\frac{3}{4}\\right)=\\frac{\\pi}{4\\sin(\\pi/4)}=\\frac{\\pi}{2\\sqrt{2}}$ 這類積分都能一行算完。"],"collapsible":true}],"workedExamples":[{"title":"半圓的面積","prompt":"$\\int_0^1\\sqrt{x(1-x)}\\,dx$","problemId":"burst-int-008","steps":["$\\sqrt{x(1-x)}=x^{1/2}(1-x)^{1/2}$，次方加 $1$：$\\mathrm{B}\\left(\\frac{3}{2},\\frac{3}{2}\\right)$。","$\\mathrm{B}\\left(\\frac{3}{2},\\frac{3}{2}\\right)=\\frac{\\Gamma(3/2)^2}{\\Gamma(3)}=\\frac{(\\sqrt{\\pi}/2)^2}{2}=\\frac{\\pi/4}{2}=\\frac{\\pi}{8}$。","幾何檢查：$y=\\sqrt{x(1-x)}$ 是以 $\\left(\\frac{1}{2},0\\right)$ 為圓心、半徑 $\\frac{1}{2}$ 的上半圓，面積 $\\frac{1}{2}\\pi\\left(\\frac{1}{2}\\right)^2=\\frac{\\pi}{8}$。"],"answer":"$\\frac{\\pi}{8}$"},{"title":"一端無界","prompt":"$\\int_0^1 x^{-1/2}(1-x)^{3/2}\\,dx$","problemId":"rel-boss-005","steps":["$p-1=-\\frac{1}{2}$，$p=\\frac{1}{2}$；$q-1=\\frac{3}{2}$，$q=\\frac{5}{2}$。$p$、$q>0$，收斂。","$\\mathrm{B}\\left(\\frac{1}{2},\\frac{5}{2}\\right)=\\frac{\\Gamma(1/2)\\Gamma(5/2)}{\\Gamma(3)}$。","$\\Gamma\\left(\\frac{1}{2}\\right)=\\sqrt{\\pi}$，$\\Gamma\\left(\\frac{5}{2}\\right)=\\frac{3\\sqrt{\\pi}}{4}$，$\\Gamma(3)=2$：$\\frac{\\sqrt{\\pi}\\cdot 3\\sqrt{\\pi}/4}{2}=\\frac{3\\pi}{8}$。"],"answer":"$\\frac{3\\pi}{8}$"},{"title":"$[0,\\infty)$ 上的 Beta","prompt":"$\\int_0^{\\infty}\\frac{\\sqrt{x}}{(1+x)^3}\\,dx$","problemId":"hc-spec-002","steps":["對照 $\\frac{t^{p-1}}{(1+t)^{p+q}}$（〈Beta 函數〉的變形）：$p-1=\\frac{1}{2}$，$p=\\frac{3}{2}$；$p+q=3$，$q=\\frac{3}{2}$。","積分 $=\\mathrm{B}\\left(\\frac{3}{2},\\frac{3}{2}\\right)=\\frac{\\pi}{8}$（範例 1 算過）。"],"answer":"$\\frac{\\pi}{8}$"}],"pitfalls":["漏掉分母 $\\Gamma(p+q)$，寫成 $\\mathrm{B}(p,q)=\\Gamma(p)\\Gamma(q)$。","$\\Gamma\\left(\\frac{3}{2}\\right)$ 用成 $\\sqrt{\\pi}$（那是 $\\Gamma\\left(\\frac{1}{2}\\right)$）。","$[0,\\infty)$ 形式的 $q$ 讀錯：分母的次方是 $p+q$，要減掉 $p$。","Jacobian 漏掉，或寫成 $uv$。"],"voice":"be7a6296","sections":[{"title":"公式","beats":[{"show":["$\\mathrm{B}(p,q)=\\frac{\\Gamma(p)\\,\\Gamma(q)}{\\Gamma(p+q)}$"],"say":"Beta 可以完全用 Gamma 表示：上面兩個 Gamma 相乘，下面是 Gamma p 加 q。","t":[0,6696]},{"show":["整數時：$\\frac{(m-1)!(n-1)!}{(m+n-1)!}$"],"note":"因為 $\\Gamma(m)=(m-1)!$。","say":"整數的時候，Gamma m 就是 m 減一的階乘，正好回到上一課的公式。","t":[6696,13152]},{"show":["是三個 Gamma，不是兩個"],"note":"分母 $\\Gamma(p+q)$ 最容易漏掉。","say":"最容易漏的是分母。Beta 是三個 Gamma 的組合，不是兩個相乘就好。","t":[13152,20112]}],"check":0},{"title":"非整數也能算","beats":[{"show":["$\\mathrm{B}\\left(\\frac{1}{2},\\frac{1}{2}\\right)=\\frac{\\Gamma(1/2)^2}{\\Gamma(1)}$"],"note":"分母 $\\Gamma(1)=1$。","say":"有了這條公式，非整數的 Beta 也能算。Beta 二分之一、二分之一，是 Gamma 二分之一的平方。","t":[20112,29376]},{"show":["直接積：$\\int_0^1\\frac{dx}{\\sqrt{x(1-x)}}=\\pi$"],"note":"令 $x=\\sin^2\\theta$，變成 $\\int_0^{\\pi/2}2\\,d\\theta$。","say":"另一方面直接積：令 x 等於 sine 平方 theta，積分變成二從零積到二分之 pi，就是 pi。","t":[29376,37632]},{"show":["$\\Gamma\\left(\\frac{1}{2}\\right)^2=\\pi$"],"note":"跟極座標的算法同一個答案。","say":"兩邊一比，Gamma 二分之一的平方就是 pi，又證了一次它等於根號 pi。","t":[37632,44208]}],"check":1},{"title":"為什麼成立","beats":[{"show":["$\\Gamma(p)\\Gamma(q)$","$=\\iint x^{p-1}y^{q-1}e^{-(x+y)}\\,dx\\,dy$"],"note":"第一象限上的二重積分。","say":"把兩個 Gamma 相乘，寫成第一象限上的二重積分。指數只跟 x 加 y 有關。","t":[44208,51816]},{"show":["$u=x+y$，$v=\\frac{x}{x+y}$"],"note":"$x=uv$，$y=u(1-v)$；$u\\in[0,\\infty)$，$v\\in[0,1]$。","say":"所以換兩個新變數：u 是總和，v 是 x 佔的比例。u 從零到無限大，v 從零到一，剛好蓋滿第一象限。","t":[51816,62352]},{"show":["只有 $u$ 的部分 × 只有 $v$ 的部分"],"note":"$u$ 那邊是 $\\Gamma(p+q)$，$v$ 那邊是 $\\mathrm{B}(p,q)$。","say":"代進去再乘上 Jacobian，被積函數拆成只有 u 乘只有 v，分開算：一邊是 Gamma p 加 q，一邊是 Beta。","t":[62352,71568]}],"check":3},{"title":"半圓的面積","beats":[{"show":["$\\int_0^1\\sqrt{x(1-x)}\\,dx$"],"note":"$x^{1/2}(1-x)^{1/2}$，次方加 $1$。","say":"根號 x 乘一減 x，是 x 和一減 x 都開根號，次方各加一，是 Beta 二分之三、二分之三。","t":[71568,80496]},{"show":["$\\frac{\\Gamma(3/2)^2}{\\Gamma(3)}$"],"note":"$\\Gamma\\left(\\frac{3}{2}\\right)=\\frac{\\sqrt{\\pi}}{2}$，$\\Gamma(3)=2$。","say":"用公式：Gamma 二分之三的平方，除以 Gamma 三。Gamma 二分之三是二分之根號 pi。","t":[80496,89040]}],"predict":{"ask":"答案是？","options":[{"label":"$\\frac{\\pi}{8}$：半徑 $\\frac{1}{2}$ 的半圓","correct":true},{"label":"$\\frac{\\pi}{4}$","why":"那是分子 $\\left(\\frac{\\sqrt{\\pi}}{2}\\right)^2$；還要除以 $\\Gamma(3)=2$。"},{"label":"$\\frac{\\pi}{2}$","why":"把 $\\Gamma\\left(\\frac{3}{2}\\right)$ 用成 $\\sqrt{\\pi}$；那是 $\\Gamma\\left(\\frac{1}{2}\\right)$。"}]}},{"title":"一端無界也行","beats":[{"show":["$\\int_0^1 x^{-1/2}(1-x)^{3/2}\\,dx$"],"note":"$p=\\frac{1}{2}$，$q=\\frac{5}{2}$，都 $>0$，收斂。","say":"x 的負二分之一次方在零衝到無限大，但 p 是二分之一、q 是二分之五，都大於零，收斂。","t":[89040,98160]},{"show":["$\\frac{\\Gamma(1/2)\\Gamma(5/2)}{\\Gamma(3)}=\\frac{3\\pi}{8}$"],"say":"根號 pi 乘四分之三根號 pi，再除以二，得八分之三 pi。","t":[98160,104112]},{"show":["$\\int_0^{\\infty}\\frac{\\sqrt{x}}{(1+x)^3}\\,dx=\\mathrm{B}\\left(\\frac{3}{2},\\frac{3}{2}\\right)$"],"note":"$p=\\frac{3}{2}$；$p+q=3$，$q=\\frac{3}{2}$。","say":"零到無限大的形式也一樣：分母的三次方是 p 加 q，減掉 p 才是 q。答案又是八分之 pi。","t":[104112,113568]}],"check":2}],"checks":[{"ask":"$\\mathrm{B}(p,q)$ 用 Gamma 表示是？","options":[{"label":"$\\frac{\\Gamma(p)\\Gamma(q)}{\\Gamma(p+q)}$","correct":true},{"label":"$\\Gamma(p)\\Gamma(q)$","why":"少了分母 $\\Gamma(p+q)$；例如 $\\mathrm{B}(1,2)=\\frac{1}{2}$，但 $\\Gamma(1)\\Gamma(2)=1$，要再除以 $\\Gamma(3)=2$ 才對得上。"},{"label":"$\\frac{\\Gamma(p+q)}{\\Gamma(p)\\Gamma(q)}$","why":"上下顛倒了；$\\mathrm{B}(1,2)=\\frac{1}{2}$，代進去會得到 $2$。"}]},{"ask":"$\\mathrm{B}\\left(\\frac{1}{2},\\frac{1}{2}\\right)$ 是？","options":[{"label":"$\\pi$","correct":true},{"label":"$\\sqrt{\\pi}$","why":"$\\Gamma\\left(\\frac{1}{2}\\right)^2=(\\sqrt{\\pi})^2=\\pi$，分母 $\\Gamma(1)=1$。"},{"label":"$2$","why":"$2$ 是 $\\mathrm{B}\\left(\\frac{1}{2},1\\right)=\\frac{\\Gamma(1/2)\\Gamma(1)}{\\Gamma(3/2)}=\\frac{\\sqrt{\\pi}}{\\sqrt{\\pi}/2}$。"}]},{"ask":"$\\mathrm{B}\\left(\\frac{3}{2},\\frac{1}{2}\\right)$ 是？","options":[{"label":"$\\frac{\\pi}{2}$","correct":true},{"label":"$\\frac{\\pi}{4}$","why":"分母是 $\\Gamma(2)=1$：$\\frac{(\\sqrt{\\pi}/2)(\\sqrt{\\pi})}{1}=\\frac{\\pi}{2}$。"},{"label":"$\\pi$","why":"$\\Gamma\\left(\\frac{3}{2}\\right)=\\frac{\\sqrt{\\pi}}{2}$，不是 $\\sqrt{\\pi}$。"}]},{"ask":"證明裡用 $x=uv$、$y=u(1-v)$ 換變數，Jacobian 的絕對值是？","options":[{"label":"$u$","correct":true},{"label":"$1$","why":"這個變換會拉伸面積：行列式 $v(-u)-u(1-v)=-u$。"},{"label":"$uv$","why":"算行列式時 $v$ 的項會消掉，剩 $-u$。"}]}],"practice":[{"id":"mob-trap-012","core":true},{"id":"mob-beta-005","core":true},{"id":"mob-beta-006","core":true},{"id":"mob-beta-007","core":true},{"id":"burst-int-008","core":true},{"id":"rel-boss-005","core":true},{"id":"hc-spec-002"},{"id":"burst-int-029","challenge":true,"note":"挑戰：令 $u=x^2$，化成 $[0,\\infty)$ 的 Beta，再用反射公式。"}]},"beta-trig":{"id":"beta-trig","prerequisites":["beta-gamma-relation","trig-integral-sin-cos","u-sub-definite"],"next":["wallis-beta"],"related":["wallis-integral"],"objectives":["用 $x=\\sin^2\\theta$ 推出 $\\int_0^{\\pi/2}\\sin^{2p-1}\\theta\\cos^{2q-1}\\theta\\,d\\theta=\\frac{1}{2}\\mathrm{B}(p,q)$。","看到 $\\int_0^{\\pi/2}\\sin^m\\theta\\cos^n\\theta\\,d\\theta$ 就寫成 $\\frac{1}{2}\\mathrm{B}\\left(\\frac{m+1}{2},\\frac{n+1}{2}\\right)$，再用 Gamma 算。","從 $m$、$n$ 的奇偶預測答案有沒有 $\\pi$，處理分數次方（例如 $\\sqrt{\\tan\\theta}$）。"],"concept":[{"heading":"① 從 $[0,1]$ 搬到 $\\left[0,\\frac{\\pi}{2}\\right]$","body":["在 $\\mathrm{B}(p,q)=\\int_0^1 x^{p-1}(1-x)^{q-1}\\,dx$ 裡令 $x=\\sin^2\\theta$：$1-x=\\cos^2\\theta$，$dx=2\\sin\\theta\\cos\\theta\\,d\\theta$，$x$ 從 $0$ 到 $1$ 對應 $\\theta$ 從 $0$ 到 $\\frac{\\pi}{2}$。","$x^{p-1}=\\sin^{2p-2}\\theta$，$(1-x)^{q-1}=\\cos^{2q-2}\\theta$，再乘上 $2\\sin\\theta\\cos\\theta$，次方各加 $1$："],"tex":["\\int_0^{\\pi/2}\\sin^{2p-1}\\theta\\,\\cos^{2q-1}\\theta\\,d\\theta=\\tfrac12\\,B(p,q)"]},{"heading":"② 實際使用：次方加 1 再除以 2","body":["題目是 $\\sin^m\\theta\\cos^n\\theta$ 時，令 $2p-1=m$、$2q-1=n$，也就是 $p=\\frac{m+1}{2}$、$q=\\frac{n+1}{2}$：","$\\int_0^{\\pi/2}\\sin^m\\theta\\cos^n\\theta\\,d\\theta=\\frac{1}{2}\\mathrm{B}\\left(\\frac{m+1}{2},\\frac{n+1}{2}\\right)=\\frac{\\Gamma\\left(\\frac{m+1}{2}\\right)\\Gamma\\left(\\frac{n+1}{2}\\right)}{2\\Gamma\\left(\\frac{m+n+2}{2}\\right)}$。","條件：$m>-1$、$n>-1$（對應 $p$、$q>0$），所以分數次方、甚至負的次方（大於 $-1$）都可以。"]},{"heading":"③ 從奇偶預測答案","body":["$m$、$n$ 都是偶數：$\\frac{m+1}{2}$、$\\frac{n+1}{2}$ 都是半整數，各帶一個 $\\sqrt{\\pi}$，分母是整數點，答案帶 $\\pi$。","至少一個是奇數：那一個的 Gamma 是整數點；另一個的 $\\sqrt{\\pi}$ 會跟分母（也是半整數）的 $\\sqrt{\\pi}$ 約掉，答案是有理數。這跟〈sinᵐ x cosⁿ x〉裡「有奇數次方就用換元」的經驗一致。"]}],"workedExamples":[{"title":"有奇數次方","prompt":"$\\int_0^{\\pi/2}\\sin^5\\theta\\cos^3\\theta\\,d\\theta$","problemId":"burst-int-018","steps":["$m=5$、$n=3$：$p=3$、$q=2$，積分 $=\\frac{1}{2}\\mathrm{B}(3,2)$。","$\\mathrm{B}(3,2)=\\frac{2!\\,1!}{4!}=\\frac{2}{24}=\\frac{1}{12}$。","答案 $\\frac{1}{2}\\cdot\\frac{1}{12}=\\frac{1}{24}$。有奇數次方，答案沒有 $\\pi$。"],"answer":"$\\frac{1}{24}$"},{"title":"兩個都是偶數","prompt":"$\\int_0^{\\pi/2}\\sin^4\\theta\\cos^2\\theta\\,d\\theta$","problemId":"rel-hard-int-007","steps":["$m=4$、$n=2$：$p=\\frac{5}{2}$、$q=\\frac{3}{2}$，積分 $=\\frac{1}{2}\\mathrm{B}\\left(\\frac{5}{2},\\frac{3}{2}\\right)$。","$\\mathrm{B}\\left(\\frac{5}{2},\\frac{3}{2}\\right)=\\frac{\\Gamma(5/2)\\Gamma(3/2)}{\\Gamma(4)}=\\frac{(3\\sqrt{\\pi}/4)(\\sqrt{\\pi}/2)}{6}=\\frac{3\\pi/8}{6}=\\frac{\\pi}{16}$。","答案 $\\frac{1}{2}\\cdot\\frac{\\pi}{16}=\\frac{\\pi}{32}$，跟〈Wallis 積分〉用 $W_4-W_6$ 算的一樣。"],"answer":"$\\frac{\\pi}{32}$"},{"title":"分數次方","prompt":"$\\int_0^{\\pi/2}\\sqrt{\\tan\\theta}\\,d\\theta$","problemId":"world-065","steps":["$\\sqrt{\\tan\\theta}=\\sin^{1/2}\\theta\\cos^{-1/2}\\theta$。$m=\\frac{1}{2}$、$n=-\\frac{1}{2}$（$>-1$，收斂）：$p=\\frac{3}{4}$、$q=\\frac{1}{4}$。","積分 $=\\frac{1}{2}\\mathrm{B}\\left(\\frac{3}{4},\\frac{1}{4}\\right)=\\frac{1}{2}\\cdot\\frac{\\Gamma(3/4)\\Gamma(1/4)}{\\Gamma(1)}$。","用反射公式 $\\Gamma(s)\\Gamma(1-s)=\\frac{\\pi}{\\sin(\\pi s)}$（〈Beta 與 Gamma 的關係〉的預告）：$\\Gamma\\left(\\frac{1}{4}\\right)\\Gamma\\left(\\frac{3}{4}\\right)=\\frac{\\pi}{\\sin(\\pi/4)}=\\pi\\sqrt{2}$。","答案 $\\frac{1}{2}\\pi\\sqrt{2}=\\frac{\\pi}{\\sqrt{2}}\\approx 2.221$。"],"answer":"$\\frac{\\pi}{\\sqrt{2}}$"}],"pitfalls":["忘了前面的 $\\frac{1}{2}$。","$p$、$q$ 讀成 $m$、$n$ 本身，或讀成 $m+1$、$n+1$（沒有除以 $2$）。","$\\Gamma\\left(\\frac{m+n+2}{2}\\right)$ 寫成 $\\Gamma\\left(\\frac{m+n}{2}\\right)$：分母的參數是 $p+q=\\frac{m+n+2}{2}$。","負的次方小於等於 $-1$ 時也套公式；那時積分發散。"],"voice":"91865a1b","sections":[{"title":"搬到 $\\left[0,\\frac{\\pi}{2}\\right]$","beats":[{"show":["令 $x=\\sin^2\\theta$"],"note":"$1-x=\\cos^2\\theta$；$x:0\\to 1$ 對應 $\\theta:0\\to\\frac{\\pi}{2}$。","say":"在 Beta 的積分裡令 x 等於 sine 平方 theta，一減 x 就是 cosine 平方，區間變成零到二分之 pi。","t":[0,8328]},{"show":["$x^{p-1}=\\sin^{2p-2}\\theta$，$(1-x)^{q-1}=\\cos^{2q-2}\\theta$"],"say":"x 的 p 減一次方變成 sine 的二 p 減二次方，cosine 那邊也一樣。","t":[8328,14520]},{"show":["$dx=2\\sin\\theta\\cos\\theta\\,d\\theta$"],"say":"dx 也要換：它帶來一個二，還有一個 sine、一個 cosine。","t":[14520,20088]}],"predict":{"ask":"全部乘起來，$\\sin\\theta$ 的次方是？","options":[{"label":"$2p-1$","correct":true},{"label":"$2p-2$","why":"忘了 $dx$ 帶來的那一個 $\\sin\\theta$，次方要再加 $1$。"},{"label":"$p-1$","why":"$x=\\sin^2\\theta$，所以 $x^{p-1}$ 是 $\\sin^{2p-2}\\theta$，次方要乘 $2$。"}]}},{"title":"加 1 再除以 2","beats":[{"show":["$\\int_0^{\\pi/2}\\sin^{2p-1}\\theta\\cos^{2q-1}\\theta\\,d\\theta$","$=\\frac{1}{2}\\mathrm{B}(p,q)$"],"note":"$dx$ 的 $2$ 移到另一邊，變成 $\\frac{1}{2}$。","say":"dx 帶來的二移到另一邊，三角形式的積分就是 Beta 的一半。","t":[20088,26016]},{"show":["$\\sin^m\\theta\\cos^n\\theta$：$p=\\frac{m+1}{2}$，$q=\\frac{n+1}{2}$"],"say":"實際用的時候，題目是 sine 的 m 次方乘 cosine 的 n 次方，次方先加一，再除以二。","t":[26016,33912]},{"show":["條件：$m>-1$，$n>-1$"],"note":"分數次方、負的次方都可以。","say":"條件是 m、n 都大於負一，對應 p、q 大於零。分數次方、甚至負的次方都能用。","t":[33912,42840]}],"check":1},{"title":"有奇數次方","beats":[{"show":["$\\int_0^{\\pi/2}\\sin^5\\theta\\cos^3\\theta\\,d\\theta$"],"note":"$m=5$，$n=3$：$p=3$，$q=2$。","say":"sine 五次方乘 cosine 三次方：五加一除以二是三，三加一除以二是二。","t":[42840,49944]},{"show":["$\\frac{1}{2}\\mathrm{B}(3,2)=\\frac{1}{2}\\cdot\\frac{2!\\,1!}{4!}=\\frac{1}{24}$"],"say":"Beta 三、二是二十四分之二，也就是十二分之一，再乘二分之一，得二十四分之一。","t":[49944,58224]}],"check":0},{"title":"從奇偶看答案","beats":[{"show":["$\\int_0^{\\pi/2}\\sin^4\\theta\\cos^2\\theta\\,d\\theta$"],"note":"$p=\\frac{5}{2}$，$q=\\frac{3}{2}$。","say":"換成兩個都是偶數：sine 四次方乘 cosine 平方，p 是二分之五，q 是二分之三。","t":[58224,66144]},{"show":["$\\frac{1}{2}\\cdot\\frac{\\Gamma(5/2)\\Gamma(3/2)}{\\Gamma(4)}=\\frac{\\pi}{32}$"],"note":"跟 Wallis 的 $W_4-W_6$ 一樣。","say":"兩個半整數各帶一個根號 pi，分母 Gamma 四是六，答案三十二分之 pi，跟 Wallis 算的一樣。","t":[66144,74376]},{"show":["都偶數：帶 $\\pi$","有奇數：有理數"],"say":"規律是：兩個都偶數，答案帶 pi；只要有一個奇數，根號 pi 會上下約掉，答案是有理數。","t":[74376,83424]}],"check":3},{"title":"分數次方","beats":[{"show":["$\\sqrt{\\tan\\theta}=\\sin^{1/2}\\theta\\cos^{-1/2}\\theta$"],"note":"$n=-\\frac{1}{2}>-1$，收斂。","say":"根號 tangent 寫成 sine 的二分之一次方乘 cosine 的負二分之一次方。負二分之一大於負一，收斂。","t":[83424,92712]},{"show":["$=\\frac{1}{2}\\mathrm{B}\\left(\\frac{3}{4},\\frac{1}{4}\\right)$"],"note":"$p=\\frac{3}{4}$，$q=\\frac{1}{4}$。","say":"次方加一再除以二：p 是四分之三，q 是四分之一。","t":[92712,98304]},{"show":["$\\int_0^{\\pi/2}\\sqrt{\\tan\\theta}\\,d\\theta=\\frac{\\pi}{\\sqrt{2}}$"],"note":"用反射公式 $\\Gamma\\left(\\frac{1}{4}\\right)\\Gamma\\left(\\frac{3}{4}\\right)=\\pi\\sqrt{2}$。","say":"再借反射公式，答案是根號二分之 pi，大約二點二二一。","t":[98304,104184]}],"check":2}],"checks":[{"ask":"$\\int_0^{\\pi/2}\\sin^3\\theta\\cos^2\\theta\\,d\\theta$ 是？","options":[{"label":"$\\frac{2}{15}$","correct":true},{"label":"$\\frac{4}{15}$","why":"$\\mathrm{B}\\left(2,\\frac{3}{2}\\right)=\\frac{\\Gamma(2)\\Gamma(3/2)}{\\Gamma(7/2)}=\\frac{4}{15}$，但公式前面還有 $\\frac{1}{2}$。"},{"label":"$\\frac{2\\pi}{15}$","why":"$\\sin$ 的次方是奇數，$\\sqrt{\\pi}$ 會上下約掉，答案沒有 $\\pi$。"}]},{"ask":"$\\int_0^{\\pi/2}\\sin^6\\theta\\cos^4\\theta\\,d\\theta$ 寫成 Beta 是？","options":[{"label":"$\\frac{1}{2}\\mathrm{B}\\left(\\frac{7}{2},\\frac{5}{2}\\right)$","correct":true},{"label":"$\\frac{1}{2}\\mathrm{B}(6,4)$","why":"要先加 $1$ 再除以 $2$：$p=\\frac{6+1}{2}=\\frac{7}{2}$。"},{"label":"$\\mathrm{B}\\left(\\frac{7}{2},\\frac{5}{2}\\right)$","why":"$x=\\sin^2\\theta$ 換元時 $dx=2\\sin\\theta\\cos\\theta\\,d\\theta$，所以三角形式是 Beta 的一半。"}]},{"ask":"$\\int_0^{\\pi/2}\\frac{d\\theta}{\\sqrt{\\sin\\theta}}$ 收斂嗎？","options":[{"label":"收斂：$m=-\\frac{1}{2}>-1$","correct":true},{"label":"發散：被積函數在 $\\theta=0$ 無界","why":"無界不等於發散；$\\theta\\to 0$ 時 $\\sin\\theta\\sim\\theta$，被積函數像 $\\theta^{-1/2}$，$p=\\frac{1}{2}<1$。"},{"label":"不能用 Beta，因為次方是負的","why":"次方大於 $-1$ 都可以：對應 $p=\\frac{1}{4}>0$。"}]},{"ask":"$\\int_0^{\\pi/2}\\sin^4\\theta\\cos^3\\theta\\,d\\theta$ 的答案：","options":[{"label":"是有理數（沒有 $\\pi$）","correct":true},{"label":"帶 $\\pi$，因為 $\\sin$ 的次方是偶數","why":"只要有一個是奇數就沒有 $\\pi$：$\\Gamma\\left(\\frac{5}{2}\\right)$ 的 $\\sqrt{\\pi}$ 會被分母 $\\Gamma\\left(\\frac{9}{2}\\right)$ 的 $\\sqrt{\\pi}$ 約掉。實際值是 $\\frac{2}{35}$。"},{"label":"帶 $\\sqrt{\\pi}$","why":"分子的 $\\sqrt{\\pi}$ 跟分母 $\\Gamma\\left(\\frac{9}{2}\\right)$ 的 $\\sqrt{\\pi}$ 正好約掉。"}]}],"practice":[{"id":"uni-int-016","core":true},{"id":"burst-int-018","core":true},{"id":"hc-rad-007","core":true},{"id":"burst-int-016","core":true},{"id":"burst-int-017","core":true},{"id":"burst-int-024","core":true},{"id":"burst-int-023"},{"id":"burst-int-019"},{"id":"burst-int-035"},{"id":"burst-int-032"},{"id":"burst-boss-int-017","challenge":true,"note":"挑戰：$\\sin^8\\cos^8$，次方大但公式一樣；分母 $\\Gamma(9)=8!$。"},{"id":"world-065","challenge":true,"note":"挑戰：要用反射公式 $\\Gamma\\left(\\frac{1}{4}\\right)\\Gamma\\left(\\frac{3}{4}\\right)=\\pi\\sqrt{2}$。"}]},"wallis-beta":{"id":"wallis-beta","prerequisites":["beta-trig","wallis-integral","wallis-product"],"next":["parameter-integral"],"related":["gamma-half","stirling"],"objectives":["把 Wallis 積分寫成 $W_n=\\frac{1}{2}\\mathrm{B}\\left(\\frac{n+1}{2},\\frac{1}{2}\\right)=\\frac{\\sqrt{\\pi}\\,\\Gamma\\left(\\frac{n+1}{2}\\right)}{2\\Gamma\\left(\\frac{n}{2}+1\\right)}$，並從 Gamma 遞迴推回 $W_n=\\frac{n-1}{n}W_{n-2}$。","用這個式子處理遞迴做不到的非整數次方，例如 $\\int_0^{\\pi/2}\\sqrt{\\sin x}\\,dx$。","說得出 Wallis、Beta、Gamma、$\\Gamma\\left(\\frac{1}{2}\\right)=\\sqrt{\\pi}$ 怎麼互相推出，以及 $W_n\\sim\\sqrt{\\frac{\\pi}{2n}}$。"],"concept":[{"heading":"① Wallis 是三角 Beta 的特例","body":["上一課：$\\int_0^{\\pi/2}\\sin^m\\theta\\cos^n\\theta\\,d\\theta=\\frac{1}{2}\\mathrm{B}\\left(\\frac{m+1}{2},\\frac{n+1}{2}\\right)$。Wallis 積分是 $m=n$、$\\cos$ 的次方 $0$ 的情況，所以 $q=\\frac{1}{2}$：","$W_n=\\frac{1}{2}\\mathrm{B}\\left(\\frac{n+1}{2},\\frac{1}{2}\\right)=\\frac{\\Gamma\\left(\\frac{n+1}{2}\\right)\\Gamma\\left(\\frac{1}{2}\\right)}{2\\Gamma\\left(\\frac{n}{2}+1\\right)}$。"],"tex":["W_n=\\int_0^{\\pi/2}\\sin^{n}x\\,dx=\\frac{\\sqrt{\\pi}\\;\\Gamma\\!\\left(\\frac{n+1}{2}\\right)}{2\\,\\Gamma\\!\\left(\\frac{n}{2}+1\\right)}"]},{"heading":"② 遞迴是 Gamma 遞迴的影子","body":["把 $n$ 換成 $n-2$，分子分母的 Gamma 參數各少 $1$。用 $\\Gamma(s)=(s-1)\\Gamma(s-1)$：$\\frac{W_n}{W_{n-2}}=\\left[\\frac{\\frac{n-1}{2}\\Gamma\\left(\\frac{n-1}{2}\\right)}{\\frac{n}{2}\\Gamma\\left(\\frac{n}{2}\\right)}\\right]\\div\\left[\\frac{\\Gamma\\left(\\frac{n-1}{2}\\right)}{\\Gamma\\left(\\frac{n}{2}\\right)}\\right]=\\frac{n-1}{n}$。","所以〈Wallis 積分〉的分部積分遞迴，跟 Gamma 的 $\\Gamma(s+1)=s\\Gamma(s)$ 是同一件事；偶數有 $\\pi$、奇數沒有，則是因為半整數的 Gamma 帶 $\\sqrt{\\pi}$。"]},{"heading":"③ 遞迴做不到的：非整數次方","body":["$\\int_0^{\\pi/2}\\sin^{1/3}x\\,dx$、$\\int_0^{\\pi/2}\\sqrt{\\sin x}\\,dx$ 無法用 $n\\to n-2$ 的遞迴降到 $W_0$ 或 $W_1$。但 Gamma 公式對任何 $n>-1$ 都成立，答案可以寫成 Gamma 值的組合。"]},{"heading":"④ 一圈閉合的推導","body":["$n=0$：$W_0=\\frac{\\pi}{2}$，而公式給 $\\frac{\\Gamma(1/2)^2}{2\\Gamma(1)}=\\frac{\\Gamma(1/2)^2}{2}$。所以 $\\Gamma\\left(\\frac{1}{2}\\right)^2=\\pi$，這是 $\\Gamma\\left(\\frac{1}{2}\\right)=\\sqrt{\\pi}$ 的第三種證明（前兩種是極座標與 $\\mathrm{B}\\left(\\frac{1}{2},\\frac{1}{2}\\right)$）。","$n$ 很大時，$\\frac{\\Gamma(x+1/2)}{\\Gamma(x+1)}\\sim x^{-1/2}$（可由〈Stirling 公式〉推出），得 $W_n\\sim\\sqrt{\\frac{\\pi}{2n}}$，跟〈Wallis 乘積〉裡由 $nW_nW_{n-1}=\\frac{\\pi}{2}$ 得到的一樣。"]}],"workedExamples":[{"title":"用 Gamma 算 $W_7$","prompt":"$\\int_0^{\\pi/2}\\sin^7 x\\,dx$","problemId":"burst-int-021","steps":["$W_7=\\frac{1}{2}\\mathrm{B}\\left(4,\\frac{1}{2}\\right)=\\frac{\\Gamma(4)\\Gamma(1/2)}{2\\Gamma(9/2)}$。","$\\Gamma(4)=6$，$\\Gamma\\left(\\frac{9}{2}\\right)=\\frac{7}{2}\\cdot\\frac{5}{2}\\cdot\\frac{3}{2}\\cdot\\frac{1}{2}\\sqrt{\\pi}=\\frac{105\\sqrt{\\pi}}{16}$。","$W_7=\\frac{6\\sqrt{\\pi}}{2\\cdot 105\\sqrt{\\pi}/16}=\\frac{6\\cdot 16}{210}=\\frac{96}{210}=\\frac{16}{35}$。跟遞迴 $\\frac{6}{7}\\cdot\\frac{4}{5}\\cdot\\frac{2}{3}=\\frac{16}{35}$ 一致。"],"answer":"$\\frac{16}{35}$"},{"title":"非整數次方","prompt":"把 $\\int_0^{\\pi/2}\\sqrt{\\sin x}\\,dx$ 寫成 Gamma 值。","steps":["$n=\\frac{1}{2}$：$\\frac{1}{2}\\mathrm{B}\\left(\\frac{3}{4},\\frac{1}{2}\\right)=\\frac{\\Gamma(3/4)\\Gamma(1/2)}{2\\Gamma(5/4)}$。","$\\Gamma\\left(\\frac{1}{2}\\right)=\\sqrt{\\pi}$，$\\Gamma\\left(\\frac{5}{4}\\right)=\\frac{1}{4}\\Gamma\\left(\\frac{1}{4}\\right)$。","答案 $\\frac{\\sqrt{\\pi}\\,\\Gamma(3/4)}{2\\Gamma(5/4)}=\\frac{2\\sqrt{\\pi}\\,\\Gamma(3/4)}{\\Gamma(1/4)}\\approx 1.1981$。"],"answer":"$\\frac{\\sqrt{\\pi}\\,\\Gamma(3/4)}{2\\Gamma(5/4)}\\approx 1.1981$"},{"title":"大 $n$ 的近似","prompt":"估計 $W_{100}=\\int_0^{\\pi/2}\\sin^{100}x\\,dx$。","steps":["$W_n\\sim\\sqrt{\\frac{\\pi}{2n}}$，$n=100$：$\\sqrt{\\frac{\\pi}{200}}\\approx 0.12533$。","精確值（用遞迴 $\\frac{99}{100}\\cdot\\frac{97}{98}\\cdots\\frac{1}{2}\\cdot\\frac{\\pi}{2}$）約 $0.12502$。","比值約 $0.9975$，相對誤差約 $\\frac{1}{4n}$。"],"answer":"$\\approx 0.125$"}],"pitfalls":["$q$ 寫成 $0$：$\\cos^0$ 對應 $\\frac{0+1}{2}=\\frac{1}{2}$。","分母的 Gamma 參數寫成 $\\frac{n}{2}$，正確是 $p+q=\\frac{n}{2}+1$。","以為非整數次方就「不能算」；它有 Gamma 形式的精確值，只是沒有更簡單的閉式。","$W_n\\sim\\sqrt{\\frac{\\pi}{2n}}$ 只保證比值 $\\to 1$；$n$ 小時拿來當近似值誤差不小（$n=2$ 時差約 13%）。"],"voice":"60c2c18a","sections":[{"title":"Wallis 是特例","beats":[{"show":["$\\int_0^{\\pi/2}\\sin^m\\theta\\cos^n\\theta\\,d\\theta=\\frac{1}{2}\\mathrm{B}(p,q)$"],"note":"$p=\\frac{m+1}{2}$，$q=\\frac{n+1}{2}$。","say":"上一課的三角形式：sine 的 m 次方乘 cosine 的 n 次方，是二分之一乘 Beta。","t":[0,6984]},{"show":["Wallis：$\\cos$ 的次方是 $0$"],"note":"所以 $q=\\frac{0+1}{2}=\\frac{1}{2}$，不是 $0$。","say":"Wallis 積分只有 sine，cosine 的次方是零。零加一除以二，q 是二分之一。","t":[6984,14808]},{"show":["$W_n=\\frac{\\sqrt{\\pi}\\;\\Gamma\\left(\\frac{n+1}{2}\\right)}{2\\,\\Gamma\\left(\\frac{n}{2}+1\\right)}$"],"note":"分母參數是 $p+q=\\frac{n}{2}+1$。","say":"換成 Gamma：Gamma 二分之一是根號 pi，分母的參數是 p 加 q，也就是二分之 n 加一。","t":[14808,22728]}],"check":0},{"title":"用 Gamma 算 $W_7$","beats":[{"show":["$W_7=\\frac{\\Gamma(4)\\Gamma(1/2)}{2\\Gamma(9/2)}$"],"note":"$\\Gamma(4)=6$。","say":"七加一除以二是四，所以分子是 Gamma 四乘根號 pi，分母是二乘 Gamma 二分之九。","t":[22728,30528]},{"show":["$\\Gamma\\left(\\frac{9}{2}\\right)=\\frac{105\\sqrt{\\pi}}{16}$"],"note":"$\\frac{7}{2}\\cdot\\frac{5}{2}\\cdot\\frac{3}{2}\\cdot\\frac{1}{2}\\sqrt{\\pi}$","say":"Gamma 二分之九往下拆四次，得十六分之一百零五根號 pi。","t":[30528,36312]},{"show":["$W_7=\\frac{6\\cdot 16}{210}=\\frac{16}{35}$"],"note":"跟遞迴 $\\frac{6}{7}\\cdot\\frac{4}{5}\\cdot\\frac{2}{3}$ 一致。","say":"根號 pi 上下約掉，得三十五分之十六，跟分部積分的遞迴答案一樣。","t":[36312,43032]}],"check":1},{"title":"遞迴是影子","beats":[{"show":["$n\\to n-2$：Gamma 參數各少 $1$"],"say":"把 n 換成 n 減二，分子分母的 Gamma 參數各少一。","t":[43032,47928]},{"show":["$\\Gamma(s)=(s-1)\\Gamma(s-1)$"],"note":"分子多出 $\\frac{n-1}{2}$，分母多出 $\\frac{n}{2}$。","say":"用 Gamma 的遞迴各拆一層：分子多出二分之 n 減一，分母多出二分之 n。","t":[47928,54912]}],"predict":{"ask":"$\\frac{W_n}{W_{n-2}}$ 化簡後是？","options":[{"label":"$\\frac{n-1}{n}$","correct":true},{"label":"$\\frac{n}{n-1}$","why":"上下顛倒了；$\\frac{n-1}{2}$ 在分子，$\\frac{n}{2}$ 在分母。"},{"label":"$\\frac{n-1}{2}$","why":"那只是分子多出的因子；還要除以分母多出的 $\\frac{n}{2}$。"}]}},{"title":"非整數次方","beats":[{"show":["$\\int_0^{\\pi/2}\\sqrt{\\sin x}\\,dx$"],"note":"遞迴降不到 $W_0$ 或 $W_1$。","say":"sine 的二分之一次方，用減二的遞迴永遠降不到 W 零或 W 一。","t":[54912,61320]},{"show":["$=\\frac{\\Gamma(3/4)\\Gamma(1/2)}{2\\Gamma(5/4)}\\approx 1.1981$"],"note":"$n=\\frac{1}{2}$。","say":"可是 Gamma 公式對任何大於負一的 n 都成立，答案寫成 Gamma 值，大約一點一九八一。","t":[61320,68856]},{"show":["沒有更簡單的閉式，但不是不能算"],"say":"它沒有更簡單的閉式，可是有精確的 Gamma 形式，不是不能算。","t":[68856,74856]}],"check":3},{"title":"閉合與大 $n$","beats":[{"show":["$n=0$：$\\frac{\\pi}{2}=\\frac{\\Gamma(1/2)^2}{2}$"],"note":"$\\Gamma\\left(\\frac{1}{2}\\right)^2=\\pi$ 的第三種證明。","say":"代 n 等於零：W 零是二分之 pi，公式給 Gamma 二分之一的平方除以二。又證了一次它的平方是 pi。","t":[74856,84984]},{"show":["$W_n\\sim\\sqrt{\\frac{\\pi}{2n}}$"],"note":"由 $\\frac{\\Gamma(x+1/2)}{\\Gamma(x+1)}\\sim x^{-1/2}$。","say":"n 很大時，兩個 Gamma 的比值像 x 的負二分之一次方，所以 W n 等價於根號二 n 分之 pi。","t":[84984,93432]},{"show":["$W_{100}$：估 $0.12533$，精確 $0.12502$"],"note":"相對誤差約 $\\frac{1}{4n}$。","say":"例如 n 等於一百，估計零點一二五三三，精確值零點一二五零二，已經很接近。","t":[93432,101280]}],"check":2}],"checks":[{"ask":"$W_n=\\int_0^{\\pi/2}\\sin^n x\\,dx$ 等於哪一個 Beta？","options":[{"label":"$\\frac{1}{2}\\mathrm{B}\\left(\\frac{n+1}{2},\\frac{1}{2}\\right)$","correct":true},{"label":"$\\frac{1}{2}\\mathrm{B}\\left(\\frac{n}{2},\\frac{1}{2}\\right)$","why":"$\\sin^m$ 對應 $p=\\frac{m+1}{2}$，要先加 $1$ 再除以 $2$。"},{"label":"$\\frac{1}{2}\\mathrm{B}\\left(\\frac{n+1}{2},0\\right)$","why":"$\\cos^0$ 對應 $q=\\frac{0+1}{2}=\\frac{1}{2}$；$q=0$ 會讓 Beta 發散。"}]},{"ask":"用 Gamma 公式算 $W_4$，得到？","options":[{"label":"$\\frac{3\\pi}{16}$","correct":true},{"label":"$\\frac{3\\pi}{8}$","why":"公式分母有 $2$：$\\frac{\\Gamma(5/2)\\Gamma(1/2)}{2\\Gamma(3)}=\\frac{3\\pi/4}{4}=\\frac{3\\pi}{16}$。"},{"label":"$\\frac{3\\sqrt{\\pi}}{8}$","why":"$\\Gamma\\left(\\frac{5}{2}\\right)\\Gamma\\left(\\frac{1}{2}\\right)=\\frac{3\\sqrt{\\pi}}{4}\\sqrt{\\pi}$，兩個 $\\sqrt{\\pi}$ 相乘是 $\\pi$。"}]},{"ask":"$n\\to\\infty$ 時 $W_n$ 漸近於？","options":[{"label":"$\\sqrt{\\frac{\\pi}{2n}}$","correct":true},{"label":"$\\frac{\\pi}{2n}$","why":"$nW_nW_{n-1}=\\frac{\\pi}{2}$ 給的是 $W_n^2\\sim\\frac{\\pi}{2n}$，要開根號。"},{"label":"$\\frac{1}{n}$","why":"$W_n$ 衰減得比 $\\frac{1}{n}$ 慢，是 $n^{-1/2}$ 的速度。"}]},{"ask":"下面哪一個積分，Wallis 遞迴做不到、但 Beta–Gamma 公式可以？","options":[{"label":"$\\int_0^{\\pi/2}\\sin^{1/3}x\\,dx$","correct":true},{"label":"$\\int_0^{\\pi/2}\\sin^6 x\\,dx$","why":"整數次方，遞迴降到 $W_0$ 就好。"},{"label":"$\\int_0^{\\pi/2}\\sin^4 x\\cos^2 x\\,dx$","why":"$\\cos^2=1-\\sin^2$，化成 $W_4-W_6$，遞迴就能做。"}]}],"practice":[{"id":"burst-int-021","core":true},{"id":"burst-int-022","core":true},{"id":"burst-int-033","core":true},{"id":"burst-int-034","core":true},{"id":"mob-wallis-010","core":true},{"id":"burst-boss-int-018"},{"id":"burst-boss-int-019"},{"id":"mob-tech-017"},{"id":"dm-seq-004","challenge":true,"note":"挑戰：用 $W_n\\sim\\sqrt{\\frac{\\pi}{2n}}$ 推出 $\\binom{2n}{n}$ 的漸近。"}]}});
